QT_ISI(4,{"386":["(Semua makanan halal bagi Bani Israel kecuali makanan yang diharamkan oleh Israel) atau Yakub (atas dirinya) yaitu unta yang ditimpa penyakit pada urat nadinya. Ia bernazar jika hewan itu sembuh tidak akan dimakannya, maka haramlah hukumnya bagi mereka (sebelum Taurat diturunkan) hal ini terjadi sesudah Ibrahim sedangkan pada masanya sendiri tidaklah haram sebagaimana yang telah diakuinya. (Katakanlah) kepada mereka (\"Ambillah Taurat lalu bacalah) agar nyata benar atau tidaknya ucapanmu itu (jika kamu orang-orang yang benar\") dalam masalah tersebut. Mendengar itu mereka pun kebingungan dan tak pernah mengemukakan Taurat. Maka Allah swt. berfirman:",[["۞ كُلُّ","All"],["ٱلطَّعَامِ","[the] food"],["كَانَ","was"],["حِلًّۭا","lawful"],["لِّبَنِىٓ","for (the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["إِلَّا","except"],["مَا","what"],["حَرَّمَ","made unlawful"],["إِسْرَٰٓءِيلُ","Israel"],["عَلَىٰ","upon"],["نَفْسِهِۦ","himself"],["مِن","from"],["قَبْلِ","before"],["أَن","[that]"],["تُنَزَّلَ","(was) revealed"],["ٱلتَّوْرَىٰةُ ۗ","the Taurat"],["قُلْ","Say"],["فَأْتُوا۟","So bring"],["بِٱلتَّوْرَىٰةِ","the Taurat"],["فَٱتْلُوهَآ","and recite it"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"387":["(Maka barang siapa yang mengada-adakan kedustaan terhadap Allah sesudah itu) setelah terbukti bahwa diharamkan unta itu ialah dari pihak Yakub bukan di masa Ibrahim (mereka orang-orang yang aniaya) artinya melampaui batas kebenaran hingga jatuh dalam kebatilan.",[["فَمَنِ","Then whoever"],["ٱفْتَرَىٰ","fabricates"],["عَلَى","about"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","[the] lie"],["مِنۢ","from"],["بَعْدِ","after"],["ذَٰلِكَ","that"],["فَأُو۟لَـٰٓئِكَ","then those "],["هُمُ","they"],["ٱلظَّـٰلِمُونَ","(are) the wrongdoers"]]],"388":["(Katakanlah, \"Benarlah Allah.\") dalam soal ini sebagaimana juga dalam segala soal yang diberikan-Nya (maka ikutilah olehmu agama Ibrahim) yang saya anut (yang lurus) yang meninggalkan semua agama untuk memeluk agama Islam (dan tidaklah dia termasuk golongan musyrik). Ketika mereka mengatakan bahwa kiblat mereka lebih awal dari kiblat kaum Muslimin turun pula ayat:",[["قُلْ","Say"],["صَدَقَ","(has) spoken the truth"],["ٱللَّهُ ۗ","Allah"],["فَٱتَّبِعُوا۟","then follow"],["مِلَّةَ","(the) religion"],["إِبْرَٰهِيمَ","(of) Ibrahim"],["حَنِيفًۭا","(the) upright"],["وَمَا","and not"],["كَانَ","he was"],["مِنَ","of"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"389":["(Sesungguhnya rumah yang mula-mula dibangun) untuk tempat ibadah (bagi manusia) di muka bumi (ialah yang terdapat di Bakkah) dengan ba sebagai nama lain dari Mekah. Dinamakan demikian karena Kakbah mematahkan leher orang-orang durhaka lagi aniaya. Baitullah ini dibina oleh malaikat sebelum diciptakannya Adam dan setelah itu baru dibangun pula Masjidilaksa dan jarak di antara keduanya 40 tahun sebagai tersebut dalam kedua hadis sahih. Pada sebuah hadis lain disebutkan pula bahwa Kakbahlah yang mula-mula muncul di permukaan air ketika langit dan bumi ini diciptakan sebagai buih yang putih, maka dihamparkanlah tanah dari bawahnya (diberi berkah) hal dari alladzii tadi (dan menjadi petunjuk bagi seluruh alam) karena ia merupakan kiblat mereka.",[["إِنَّ","Indeed"],["أَوَّلَ","(the) First"],["بَيْتٍۢ","House"],["وُضِعَ","set up"],["لِلنَّاسِ","for the mankind"],["لَلَّذِى","(is) the one which"],["بِبَكَّةَ","(is) at Bakkah"],["مُبَارَكًۭا","blessed"],["وَهُدًۭى","and a guidance"],["لِّلْعَـٰلَمِينَ","for the worlds"]]],"390":["(Padanya terdapat tanda-tanda yang nyata) di antaranya (makam Ibrahim) yakni batu tempat berpijaknya Ibrahim sewaktu mendirikan Baitullah itu. Kedua telapak kakinya meninggalkan bekas padanya sampai sekarang dan tetap sepanjang zaman walaupun pemerintahan yang berkuasa sudah silih berganti. Di antaranya pula dilipatgandakannya pahala kebaikan bagi yang salat di dalamnya dan burung tidak dapat terbang di atas Kakbah (dan barang siapa memasukinya menjadi amanlah dia) artinya bebas dari ancaman pembunuhan, keaniayaan dan lain-lain. (Mengerjakan haji di Baitullah itu menjadi kewajiban manusia terhadap Allah) Ada yang membaca hajja dengan makna menyengaja. Lalu sebagai badal dari 'manusia' ialah (yakni orang-orang yang sanggup mengadakan perjalanan kepadanya) yang oleh Nabi saw. ditafsirkan dengan adanya perbekalan dan kendaraan, menurut riwayat Hakim dan lain-lain. (Barang siapa yang kafir) terhadap Allah atau terhadap kewajiban haji (maka sesungguhnya Allah Maha Kaya terhadap seluruh alam) artinya tidak memerlukan manusia, jin dan malaikat serta amal ibadah mereka.",[["فِيهِ","In it"],["ءَايَـٰتٌۢ","(are) signs"],["بَيِّنَـٰتٌۭ","clear"],["مَّقَامُ","standing place"],["إِبْرَٰهِيمَ ۖ","(of) Ibrahim"],["وَمَن","and whoever"],["دَخَلَهُۥ","enters it "],["كَانَ","is"],["ءَامِنًۭا ۗ","safe"],["وَلِلَّهِ","And (due) to Allah"],["عَلَى","upon"],["ٱلنَّاسِ","the mankind"],["حِجُّ","(is) pilgrimage"],["ٱلْبَيْتِ","(of) the House"],["مَنِ","(for one) who"],["ٱسْتَطَاعَ","is able"],["إِلَيْهِ","to [it]"],["سَبِيلًۭا ۚ","(find) a way"],["وَمَن","And whoever"],["كَفَرَ","disbelieved"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["غَنِىٌّ","(is) free from need"],["عَنِ","of"],["ٱلْعَـٰلَمِينَ","the universe"]]],"391":["(Katakanlah, \"Hai Ahli Kitab! Kenapa kamu ingkar akan ayat-ayat Allah) yakni Alquran (padahal Allah menyaksikan apa yang kamu kerjakan.\") hingga akan memberinya balasan?",[["قُلْ","Say"],["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لِمَ","Why"],["تَكْفُرُونَ","(do) you disbelieve"],["بِـَٔايَـٰتِ","in (the) Verses"],["ٱللَّهِ","(of) Allah"],["وَٱللَّهُ","while Allah"],["شَهِيدٌ","(is) a Witness"],["عَلَىٰ","over"],["مَا","what"],["تَعْمَلُونَ","you do"]]],"392":["(Katakanlah, \"Hai Ahli Kitab! Kenapa kamu menghalang-halangi dari jalan Allah) dari agama-Nya (orang-orang yang beriman) melalui pendustaan kalian terhadap Nabi Muhammad saw. dan menyembunyikan sifat-sifatnya (kamu mengharap) menghendaki agama itu (menjadi bengkok) sebenarnya iwaja itu kata benda tetapi berarti sebagai kata sifat artinya bengkok atau menyimpang dari kebenaran (padahal kamu menyaksikan) mengetahui bahwa agama yang lurus lagi diridai seperti yang tercantum dalam kitab sucimu ialah agama Islam. (Dan Allah sekali-kali tidak lalai dari apa yang kamu kerjakan) berupa kekafiran dan mendustakan. Dia sengaja menangguhkan kamu sampai saatmu nanti buat menerima ganjaran dan balasan-Nya. Ayat berikut diturunkan tatkala beberapa orang Yahudi lewat pada sebagian orang-orang Aus dan Khazraj. Mereka berang melihat kerukunan mereka lalu mereka bangkit-bangkitkan fitnah yang terjadi di antara mereka di masa jahiliah sehingga mereka pun bersengketa bahkan hampir bunuh-bunuhan.",[["قُلْ","Say"],["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لِمَ","Why"],["تَصُدُّونَ","(do) you hinder"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["مَنْ","(those) who"],["ءَامَنَ","believe[d]"],["تَبْغُونَهَا","seeking (to make) it"],["عِوَجًۭا","(seem) crooked"],["وَأَنتُمْ","while you"],["شُهَدَآءُ ۗ","(are) witnesses"],["وَمَا","And not"],["ٱللَّهُ","Allah"],["بِغَـٰفِلٍ","(is) unaware"],["عَمَّا","of what"],["تَعْمَلُونَ","you do"]]],"393":["(Hai orang-orang beriman! Jika kamu mengikuti sebagian dari orang-orang yang diberi Alkitab niscaya mereka akan mengembalikan kamu menjadi kafir setelah kamu beriman.\")",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe[d]"],["إِن","If"],["تُطِيعُوا۟","you obey"],["فَرِيقًۭا","a group"],["مِّنَ","from"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["يَرُدُّوكُم","they will turn you back"],["بَعْدَ","after"],["إِيمَـٰنِكُمْ","your belief"],["كَـٰفِرِينَ","(as) disbelievers"]]],"394":["(Betapa kamu menjadi kafir) pertanyaan sebagai celaan dan membangkitkan keheranan (padahal ayat-ayat Allah dibacakan kepadamu dan rasul-Nya pun berada di tengah-tengah kamu. Barang siapa yang berpegang teguh) atau mengikuti (agama Allah, maka sesungguhnya ia telah dibimbing ke jalan yang lurus.)",[["وَكَيْفَ","And how (could)"],["تَكْفُرُونَ","you disbelieve"],["وَأَنتُمْ","while [you]"],["تُتْلَىٰ","is recited"],["عَلَيْكُمْ","upon you"],["ءَايَـٰتُ","(the) Verses"],["ٱللَّهِ","(of) Allah"],["وَفِيكُمْ","and among you"],["رَسُولُهُۥ ۗ","(is) His Messenger"],["وَمَن","And whoever"],["يَعْتَصِم","holds firmly"],["بِٱللَّهِ","to Allah"],["فَقَدْ","then surely"],["هُدِىَ","he is guided"],["إِلَىٰ","to"],["صِرَٰطٍۢ","a path"],["مُّسْتَقِيمٍۢ","straight"]]],"395":["(Hai orang-orang yang beriman, bertakwalah kamu kepada Allah sebenar-benar takwa) yaitu dengan menaati dan bukan mendurhakai, mensyukuri dan bukan mengingkari karunia-Nya dan dengan mengingat serta tidak melupakan-Nya. Kata para sahabat, \"Wahai Rasulullah! Siapakah yang sanggup melaksanakan ini?\" Maka ayat ini pun dinasakh dengan firman-Nya, \"Bertakwalah kamu kepada Allah menurut kemampuanmu.\" (dan janganlah sekali-kali kamu mati melainkan dalam keadaan beragama Islam.)",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe[d]"],["ٱتَّقُوا۟","Fear"],["ٱللَّهَ","Allah"],["حَقَّ","(as is His) right"],["تُقَاتِهِۦ","(that) He (should) be feared"],["وَلَا","and (do) not"],["تَمُوتُنَّ","die"],["إِلَّا","except"],["وَأَنتُم","[while you]"],["مُّسْلِمُونَ","(as) Muslims"]]],"396":["(Berpegang teguhlah kamu dengan tali Allah) maksudnya agama-Nya (kesemuanya dan janganlah kamu berpecah-belah) setelah menganut Islam (serta ingatlah nikmat Allah) yakni karunia-Nya (kepadamu) hai golongan Aus dan Khazraj (ketika kamu) yakni sebelum Islam (bermusuh-musuhan, maka dirukunkan-Nya) artinya dihimpun-Nya (di antara hatimu) melalui Islam (lalu jadilah kamu berkat nikmat-Nya bersaudara) dalam agama dan pemerintahan (padahal kamu telah berada dipinggir jurang neraka) sehingga tak ada lagi pilihan lain bagi kamu kecuali terjerumus ke dalamnya dan mati dalam kekafiran (lalu diselamatkan-Nya kamu daripadanya) melalui iman kalian. (Demikianlah) sebagaimana telah disebutkan-Nya tadi (Allah menjelaskan ayat-ayat-Nya supaya kamu beroleh petunjuk).",[["وَٱعْتَصِمُوا۟","And hold firmly"],["بِحَبْلِ","to (the) rope"],["ٱللَّهِ","(of) Allah"],["جَمِيعًۭا","all together"],["وَلَا","and (do) not"],["تَفَرَّقُوا۟ ۚ","be divided"],["وَٱذْكُرُوا۟","And remember"],["نِعْمَتَ","(the) Favor"],["ٱللَّهِ","(of) Allah"],["عَلَيْكُمْ","on you"],["إِذْ","when"],["كُنتُمْ","you were"],["أَعْدَآءًۭ","enemies"],["فَأَلَّفَ","then He made friendship"],["بَيْنَ","between"],["قُلُوبِكُمْ","your hearts"],["فَأَصْبَحْتُم","then you became"],["بِنِعْمَتِهِۦٓ","by His Favor"],["إِخْوَٰنًۭا","brothers"],["وَكُنتُمْ","And you were"],["عَلَىٰ","on"],["شَفَا","(the) brink"],["حُفْرَةٍۢ","(of) pit"],["مِّنَ","of"],["ٱلنَّارِ","the Fire"],["فَأَنقَذَكُم","then He saved you"],["مِّنْهَا ۗ","from it"],["كَذَٰلِكَ","Thus"],["يُبَيِّنُ","makes clear"],["ٱللَّهُ","Allah"],["لَكُمْ","for you"],["ءَايَـٰتِهِۦ","His Verses"],["لَعَلَّكُمْ","so that you may"],["تَهْتَدُونَ","(be) guided"]]],"397":["(Hendaklah ada di antara kamu satu golongan yang menyeru kepada kebaikan) ajaran Islam (dan menyuruh kepada yang makruf dan melarang dari yang mungkar. Merekalah) yakni orang-orang yang menyeru, yang menyuruh dan yang melarang tadi (orang-orang yang beruntung) atau berbahagia. 'Min' di sini untuk menunjukkan 'sebagian' karena apa yang diperintahkan itu merupakan fardu kifayah yang tidak mesti bagi seluruh umat dan tidak pula layak bagi setiap orang, misalnya orang yang bodoh.",[["وَلْتَكُن","And let there be"],["مِّنكُمْ","among you"],["أُمَّةٌۭ","[a] people"],["يَدْعُونَ","inviting"],["إِلَى","to"],["ٱلْخَيْرِ","the good"],["وَيَأْمُرُونَ","[and] enjoining"],["بِٱلْمَعْرُوفِ","the right"],["وَيَنْهَوْنَ","and forbidding"],["عَنِ","from"],["ٱلْمُنكَرِ ۚ","the wrong"],["وَأُو۟لَـٰٓئِكَ","and those "],["هُمُ","they"],["ٱلْمُفْلِحُونَ","(are) the successful ones"]]],"398":["(Dan janganlah kamu seperti orang-orang yang berpecah-belah) dalam agama mereka (dan berselisih) padanya (sesudah datang kepada mereka keterangan yang jelas) mereka itu ialah orang-orang Yahudi dan Nasrani. (Merekalah orang-orang yang mendapat siksa yang berat).",[["وَلَا","And (do) not"],["تَكُونُوا۟","be"],["كَٱلَّذِينَ","like those who"],["تَفَرَّقُوا۟","became divided"],["وَٱخْتَلَفُوا۟","and differed"],["مِنۢ","from"],["بَعْدِ","after"],["مَا","what"],["جَآءَهُمُ","came to them "],["ٱلْبَيِّنَـٰتُ ۚ","the clear proofs"],["وَأُو۟لَـٰٓئِكَ","And those"],["لَهُمْ","for them"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"399":["(Ingatlah suatu hari di mana wajah-wajah ada yang menjadi putih berseri dan ada pula yang hitam legam) maksudnya pada hari kiamat. (Adapun orang-orang yang wajahnya menjadi hitam) yakni orang-orang kafir, maka mereka dilemparkan ke dalam neraka dan dikatakan kepada mereka sebagai celaan (\"Kenapa kamu kafir setelah beriman?\") yaitu sewaktu pengambilan ikrar dulu. (\"Maka rasailah siksa disebabkan kekafiranmu itu.\")",[["يَوْمَ","(On the) Day"],["تَبْيَضُّ","would become white"],["وُجُوهٌۭ","(some) faces"],["وَتَسْوَدُّ","and would become black"],["وُجُوهٌۭ ۚ","(some) faces"],["فَأَمَّا","As for"],["ٱلَّذِينَ","those whose"],["ٱسْوَدَّتْ","turn black"],["وُجُوهُهُمْ","[their] faces "],["أَكَفَرْتُم","Did you disbelieve"],["بَعْدَ","after"],["إِيمَـٰنِكُمْ","your belief"],["فَذُوقُوا۟","Then taste"],["ٱلْعَذَابَ","the punishment"],["بِمَا","for what"],["كُنتُمْ","you used to"],["تَكْفُرُونَ","disbelieve"]]],"400":["(Adapun orang-orang yang wajahnya menjadi putih berseri) yakni orang-orang yang beriman (mereka berada dalam rahmat Allah) dalam surga-Nya (mereka kekal di dalamnya).",[["وَأَمَّا","But as for"],["ٱلَّذِينَ","those whose"],["ٱبْيَضَّتْ","turn white"],["وُجُوهُهُمْ","[their] faces"],["فَفِى","then (they will be) in"],["رَحْمَةِ","(the) Mercy"],["ٱللَّهِ","(of) Allah"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"401":["(Itulah) maksudnya ayat-ayat tadi (ayat-ayat Allah. Kami bacakan kepadamu) hai Muhammad (dengan benar, dan tiadalah Allah menghendaki keaniayaan bagi seluruh alam) misalnya dengan menjatuhkan hukuman pada mereka tanpa dosa.",[["تِلْكَ","These"],["ءَايَـٰتُ","(are the) Verses"],["ٱللَّهِ","(of) Allah"],["نَتْلُوهَا","We recite them"],["عَلَيْكَ","to you"],["بِٱلْحَقِّ ۗ","in truth"],["وَمَا","And not"],["ٱللَّهُ","Allah"],["يُرِيدُ","wants"],["ظُلْمًۭا","injustice"],["لِّلْعَـٰلَمِينَ","to the worlds"]]],"402":["(Kepunyaan Allahlah segala yang di langit dan di bumi) baik sebagai milik maupun sebagai makhluk dan hamba (dan kepada Allah kembalinya segala urusan).",[["وَلِلَّهِ","And to Allah (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and whatever"],["فِى","(is) in"],["ٱلْأَرْضِ ۚ","the earth"],["وَإِلَى","And to"],["ٱللَّهِ","Allah"],["تُرْجَعُ","will be returned"],["ٱلْأُمُورُ","the matters"]]],"403":["(Adalah kamu) hai umat Muhammad dalam ilmu Allah swt. (sebaik-baik umat yang dikeluarkan) yang ditampilkan (buat manusia, menyuruh kepada yang makruf dan melarang dari yang mungkar serta beriman kepada Allah. Sekiranya Ahli Kitab beriman, adalah ia) yakni keimanan itu (lebih baik bagi mereka. Di antara mereka ada yang beriman) misalnya Abdullah bin Salam r.a. dan sahabat-sahabatnya (tetapi kebanyakan mereka orang-orang yang fasik) kafir.",[["كُنتُمْ","You are"],["خَيْرَ","(the) best"],["أُمَّةٍ","(of) people"],["أُخْرِجَتْ","raised"],["لِلنَّاسِ","for the mankind "],["تَأْمُرُونَ","enjoining"],["بِٱلْمَعْرُوفِ","the right"],["وَتَنْهَوْنَ","and forbidding"],["عَنِ","[from]"],["ٱلْمُنكَرِ","the wrong"],["وَتُؤْمِنُونَ","and believing"],["بِٱللَّهِ ۗ","in Allah"],["وَلَوْ","And if"],["ءَامَنَ","believed"],["أَهْلُ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَكَانَ","surely would have been"],["خَيْرًۭا","good"],["لَّهُم ۚ","for them"],["مِّنْهُمُ","Among them"],["ٱلْمُؤْمِنُونَ","(are) [the] believers"],["وَأَكْثَرُهُمُ","but most of them"],["ٱلْفَـٰسِقُونَ","(are) defiantly disobedient"]]],"404":["(Mereka sekali-kali tidak akan dapat memberi mudarat kepadamu) maksudnya sedikit pun juga orang-orang Yahudi tidak akan dapat memberi mudarat terhadap kaum Muslimin (kecuali gangguan saja) yakni gangguan lisan seperti makian dan ancaman (dan jika mereka berperang dengan kamu maka mereka akan berbalik melarikan diri) karena menderita kekalahan (kemudian mereka tidak mendapat pertolongan) untuk menghadapi kamu sebaliknya kamulah yang akan mendapat pertolongan untuk menghadapi mereka.",[["لَن","Never"],["يَضُرُّوكُمْ","will they harm you"],["إِلَّآ","except"],["أَذًۭى ۖ","a hurt"],["وَإِن","And if"],["يُقَـٰتِلُوكُمْ","they fight you"],["يُوَلُّوكُمُ","they will turn (towards) you"],["ٱلْأَدْبَارَ","the backs"],["ثُمَّ","then"],["لَا","not"],["يُنصَرُونَ","they will be helped"]]],"405":["(Ditimpakan atas mereka kehinaan di mana pun mereka berada) sehingga bagi mereka tak ada kemuliaan dan keamanan (kecuali) dengan dua hal: (dengan tali dari Allah dan tali dari manusia) yang beriman, yang merupakan janji dari mereka kepada Ahli Kitab bahwa mereka akan diberi keamanan dengan imbalan pembayaran upeti, maka tak ada jaminan bagi mereka selain dengan itu (dan mereka kembali mendapat kemurkaan dari Allah dan ditimpakan atas mereka kerendahan. Demikian itu bahwa mereka) artinya disebabkan karena mereka (kafir akan ayat-ayat Allah dan membunuh para nabi tanpa alasan yang benar. Demikian itu) sebagai pengukuhan (disebabkan mereka durhaka) akan perintah Allah (dan mereka melanggar batas) artinya melampaui yang halal hingga jatuh kepada yang haram.",[["ضُرِبَتْ","Struck"],["عَلَيْهِمُ","on them"],["ٱلذِّلَّةُ","the humiliation"],["أَيْنَ","wherever"],["مَا","that"],["ثُقِفُوٓا۟","they are found"],["إِلَّا","except"],["بِحَبْلٍۢ","with a rope"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["وَحَبْلٍۢ","and a rope"],["مِّنَ","from"],["ٱلنَّاسِ","the people"],["وَبَآءُو","And they incurred"],["بِغَضَبٍۢ","wrath"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["وَضُرِبَتْ","and struck"],["عَلَيْهِمُ","on them"],["ٱلْمَسْكَنَةُ ۚ","the poverty"],["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because"],["كَانُوا۟","they used to"],["يَكْفُرُونَ","disbelieve"],["بِـَٔايَـٰتِ","in (the) Verses"],["ٱللَّهِ","(of) Allah"],["وَيَقْتُلُونَ","and they killed"],["ٱلْأَنۢبِيَآءَ","the Prophets"],["بِغَيْرِ","without"],["حَقٍّۢ ۚ","right"],["ذَٰلِكَ","That"],["بِمَا","(is) because"],["عَصَوا۟","they disobeyed"],["وَّكَانُوا۟","and they used to"],["يَعْتَدُونَ","transgress"]]],"406":["(Mereka itu tidaklah) maksudnya Ahli-ahli Kitab (sama) atau serupa. (Di antara Ahli Kitab ada golongan yang bersikap lurus) jujur dan teguh berdiri di atas kebenaran seperti Abdullah bin Salam r.a. dan sahabat-sahabatnya (mereka membaca ayat-ayat Allah di saat-saat malam hari sedangkan mereka bersujud) maksudnya salat, menjadi hal.",[["۞ لَيْسُوا۟","They are not"],["سَوَآءًۭ ۗ","(the) same"],["مِّنْ","among"],["أَهْلِ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["أُمَّةٌۭ","(is) a community"],["قَآئِمَةٌۭ","standing"],["يَتْلُونَ","(and) reciting"],["ءَايَـٰتِ","(the) Verses"],["ٱللَّهِ","(of) Allah"],["ءَانَآءَ","(in the) hours"],["ٱلَّيْلِ","(of) the night"],["وَهُمْ","and they"],["يَسْجُدُونَ","prostrate"]]],"407":["(Mereka beriman kepada Allah dan hari yang akhir, menyuruh kepada yang makruf dan melarang dari yang mungkar dan berlomba-lomba mengerjakan kebaikan. Mereka itulah) yakni yang dilukiskan tadi (termasuk orang-orang yang saleh). Di antara mereka ada pula yang tidak seperti demikian dan tidak termasuk orang-orang yang saleh.",[["يُؤْمِنُونَ","They believe"],["بِٱللَّهِ","in Allah"],["وَٱلْيَوْمِ","and the Day"],["ٱلْـَٔاخِرِ","the Last"],["وَيَأْمُرُونَ","and they enjoin"],["بِٱلْمَعْرُوفِ","[with] the right"],["وَيَنْهَوْنَ","and forbid"],["عَنِ","[from]"],["ٱلْمُنكَرِ","the wrong"],["وَيُسَـٰرِعُونَ","and they hasten"],["فِى","in"],["ٱلْخَيْرَٰتِ","the good deeds"],["وَأُو۟لَـٰٓئِكَ","And those"],["مِنَ","(are) from"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"408":["(Apa-apa yang mereka kerjakan) yang dikerjakan oleh umat yang lurus tadi, dengan ya atau yang kamu kerjakan, wahai umat dengan ta (berupa kebaikan, maka tidaklah akan tertutup) menurut dua versi tadi artinya tidaklah akan terhalang untuk mendapatkan pahalanya tetapi akan tetap diberi balasannya. (Dan Allah Maha Mengetahui akan orang-orang yang bertakwa.)",[["وَمَا","And whatever"],["يَفْعَلُوا۟","they do"],["مِنْ","of"],["خَيْرٍۢ","a good"],["فَلَن","then never"],["يُكْفَرُوهُ ۗ","will they be denied it"],["وَٱللَّهُ","And Allah"],["عَلِيمٌۢ","(is) All-Knowing"],["بِٱلْمُتَّقِينَ","of the God-fearing"]]],"409":["(Sesungguhnya orang-orang yang kafir tidaklah akan dapat menolak) menghindarkan (diri mereka atau harta benda maupun anak-anak laki-laki mereka dari Allah) dari siksa-Nya (sedikit pun juga) dikhususkan-Nya menyebutkan keduanya karena biasanya manusia membela dirinya adakalanya dengan tebusan harta dan adakalanya dengan bantuan anak-anaknya. (Dan mereka adalah penghuni neraka, kekal mereka di dalamnya.)",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["لَن","never"],["تُغْنِىَ","will avail"],["عَنْهُمْ","[for] them"],["أَمْوَٰلُهُمْ","their wealth"],["وَلَآ","and not"],["أَوْلَـٰدُهُم","their children"],["مِّنَ","against"],["ٱللَّهِ","Allah"],["شَيْـًۭٔا ۖ","anything"],["وَأُو۟لَـٰٓئِكَ","and those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلنَّارِ ۚ","(of) the Fire"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"410":["(Perumpamaan) atau sifat (harta yang mereka nafkahkan) maksudnya orang-orang kafir (dalam kehidupan dunia) yakni dalam memusuhi Nabi bahkan bersedekah dan sebagainya (seperti angin yang mengandung udara yang sangat dingin yang menimpa tanaman suatu kaum yang menganiaya diri mereka sendiri) dengan kekafiran dan berbuat maksiat (lalu dirusakkannya) tanaman itu hingga mereka tidak memperoleh manfaat darinya. Maka demikianlah pula nafkah-nafkah mereka tadi habis tidak membawa manfaat apa-apa. (Allah tidaklah menganiaya mereka) dengan lenyapnya harta benda itu tadi (tetapi merekalah yang menganiaya diri mereka sendiri) dengan kekafiran yang menyebabkan musnahnya harta mereka.",[["مَثَلُ","Example"],["مَا","(of) what"],["يُنفِقُونَ","they spend"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلْحَيَوٰةِ","[the] life"],["ٱلدُّنْيَا","(of) the world"],["كَمَثَلِ","(is) like (the) example"],["رِيحٍۢ","(of) a wind"],["فِيهَا","in it"],["صِرٌّ","(is) frost"],["أَصَابَتْ","it struck"],["حَرْثَ","(the) harvest"],["قَوْمٍۢ","(of) a people"],["ظَلَمُوٓا۟","who wronged"],["أَنفُسَهُمْ","themselves"],["فَأَهْلَكَتْهُ ۚ","then destroyed it"],["وَمَا","And not"],["ظَلَمَهُمُ","(has) wronged them"],["ٱللَّهُ","Allah"],["وَلَـٰكِنْ","[and] but"],["أَنفُسَهُمْ","themselves"],["يَظْلِمُونَ","they wronged"]]],"411":["(Hai orang-orang yang beriman! Janganlah kamu ambil sebagai orang-orang kepercayaan) maksudnya sebagai teman-teman akrab tempat kamu membukakan rahasia kamu (orang-orang yang di luar kalanganmu) maksudnya orang lain, misalnya orang Yahudi, Nasrani dan munafik (tidak henti-hentinya mereka menimbulkan kesusahan bagimu) khabaala dijadikan manshub karena dihilangkannya huruf khafadh dan arti kalimat ialah mereka tidak putus-putusnya hendak membinasakan kamu (mereka ingin) atau mencita-citakan (supaya kamu menderita) artinya berada dalam puncak kesusahan. (Telah nyata) tampak (kebencian) permusuhan terhadapmu (dari mulut-mulut mereka) dengan menjelekkan kamu dan membukakan rahasia kamu kepada orang-orang musyrik (dan apa yang disembunyikan oleh hati mereka) berupa permusuhan (lebih besar lagi. Sungguh telah Kami jelaskan kepada kamu tanda-tanda) permusuhan mereka itu (jika kamu memikirkan)nya. Maka janganlah kamu ambil mereka itu sebagai orang-orang kepercayaan.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe[d]"],["لَا","(Do) not"],["تَتَّخِذُوا۟","take"],["بِطَانَةًۭ","(as) intimates"],["مِّن","from"],["دُونِكُمْ","other than yourselves"],["لَا","not"],["يَأْلُونَكُمْ","they will spare you"],["خَبَالًۭا","(any) ruin"],["وَدُّوا۟","They wish"],["مَا","what"],["عَنِتُّمْ","distresses you"],["قَدْ","Indeed"],["بَدَتِ","(has become) apparent"],["ٱلْبَغْضَآءُ","the hatred"],["مِنْ","from"],["أَفْوَٰهِهِمْ","their mouths"],["وَمَا","and what"],["تُخْفِى","conceals"],["صُدُورُهُمْ","their breasts"],["أَكْبَرُ ۚ","(is) greater"],["قَدْ","Certainly"],["بَيَّنَّا","We made clear"],["لَكُمُ","for you"],["ٱلْـَٔايَـٰتِ ۖ","the Verses"],["إِن","if"],["كُنتُمْ","you were"],["تَعْقِلُونَ","(to use) reason"]]],"412":["(Begitulah) sebagai peringatan (kamu) hai (orang-orang) yang beriman (kalian mencintai mereka) karena akrabnya persaudaraannya dengan kamu (tetapi mereka tidak mencintai kamu) karena perbedaan agamamu dengan agama mereka (dan kamu beriman kepada kitab-kitab kesemuanya) artinya kepada semua kitab, tetapi mereka tidak beriman kepada Kitabmu. (Jika mereka menjumpai kamu, mereka berkata, \"Kami beriman,\" dan apabila mereka telah berada dalam kalangan mereka sendiri, mereka menggigit ujung-ujung jari mereka disebabkan teramat marah kepadamu) melihat kerukunan kamu. Kemarahan diibaratkan dengan menggigit ujung-ujung jari, walaupun tidak sebenarnya terjadi. (Katakanlah, \"Matilah kamu dengan kemarahanmu itu!\") artinya tetaplah dalam keadaan demikian sampai kamu mati, karena tidak akan pernah kamu melihat hal-hal yang akan menyenangkan hatimu! (Sesungguhnya Allah mengetahui apa yang terdapat di dalam dada) maksudnya segala isi hati termasuk apa yang mereka sembunyikan.",[["هَـٰٓأَنتُمْ","Lo! You are"],["أُو۟لَآءِ","those"],["تُحِبُّونَهُمْ","you love them"],["وَلَا","but not"],["يُحِبُّونَكُمْ","they love you"],["وَتُؤْمِنُونَ","and you believe"],["بِٱلْكِتَـٰبِ","in the Book "],["كُلِّهِۦ","all of it"],["وَإِذَا","And when"],["لَقُوكُمْ","they meet you"],["قَالُوٓا۟","they say"],["ءَامَنَّا","We believe"],["وَإِذَا","And when"],["خَلَوْا۟","they are alone"],["عَضُّوا۟","they bite"],["عَلَيْكُمُ","at you"],["ٱلْأَنَامِلَ","the finger tips"],["مِنَ","(out) of"],["ٱلْغَيْظِ ۚ","[the] rage"],["قُلْ","Say"],["مُوتُوا۟","Die"],["بِغَيْظِكُمْ ۗ","in your rage"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","(is) All-Knowing"],["بِذَاتِ","of what"],["ٱلصُّدُورِ","(is in) the breasts"]]],"413":["(Jika kamu disentuh) ditimpa (oleh kebaikan) atau nikmat, seperti kemenangan atau harta rampasan (mereka merasa kecewa) atau berdukacita (sebaliknya jika kamu ditimpa bencana) seperti kekalahan dan kekeringan (mereka gembira karenanya) jumlah syarat yang kedua berhubungan dengan syarat yang sebelumnya, sedangkan di antara keduanya interupsi atau kalimat sela. Makna ayat, bahwa mereka mati-matian dalam memusuhi kamu, maka kenapa kamu mempercayai mereka, jauhilah mereka itu! (Jika kamu bersabar) terhadap gangguan mereka (dan bertakwa) kepada Allah hingga tidak mempercayai mereka dan sebagainya (maka tidaklah akan mendatangkan kemudaratan) bacaannya 'laa yadhirkum' atau 'laa yadhurrukum' (tipu daya mereka sedikit pun. Sesungguhnya Allah terhadap apa yang mereka lakukan) dengan 'ya' dan 'ta' (meliputi) mengetahui dan akan memberikan balasan",[["إِن","If"],["تَمْسَسْكُمْ","touches you"],["حَسَنَةٌۭ","a good"],["تَسُؤْهُمْ","it grieves them"],["وَإِن","and if"],["تُصِبْكُمْ","strikes you"],["سَيِّئَةٌۭ","misfortune"],["يَفْرَحُوا۟","they rejoice"],["بِهَا ۖ","at it"],["وَإِن","And if"],["تَصْبِرُوا۟","you are patient"],["وَتَتَّقُوا۟","and fear (Allah)"],["لَا","not"],["يَضُرُّكُمْ","will harm you"],["كَيْدُهُمْ","their plot"],["شَيْـًٔا ۗ","(in) anything"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["بِمَا","of what"],["يَعْمَلُونَ","they do"],["مُحِيطٌۭ","(is) All-Encompassing"]]],"414":["(Dan) ingatlah hai Muhammad (ketika kamu berangkat di pagi hari dari keluargamu) yakni dari Madinah (untuk menempatkan orang-orang beriman pada beberapa tempat) atau markas di mana mereka bertahan (untuk berperang. Dan Allah Maha Mendengar) akan ucapanmu (lagi Maha Mengetahui) peri keadaanmu. Peristiwa ini terjadi pada waktu perang Uhud. Nabi saw. keluar dengan membawa 1000 atau 950 orang tentara sedangkan kaum musyrikin berjumlah sebanyak 3000 orang. Nabi saw. menduduki posisinya di lereng bukit Uhud pada hari Sabtu tanggal 7 Syawal tahun ketiga Hijriah. Punggung beliau dan punggung tentaranya menghadap ke arah bukit Uhud lalu mengatur barisan mereka dan menempatkan pasukan panah yang dipimpin oleh Abdullah bin Jubair di puncak bukit seraya bersabda, \"Hujani mereka dengan anak panah dari sini agar mereka tidak menyerang dari belakang dan jangan tinggalkan tempat ini biar sekali pun tidak kalah atau pun menang!\"",[["وَإِذْ","And when"],["غَدَوْتَ","you left early morning"],["مِنْ","from"],["أَهْلِكَ","your household"],["تُبَوِّئُ","to post"],["ٱلْمُؤْمِنِينَ","the believers"],["مَقَـٰعِدَ","(to take) positions"],["لِلْقِتَالِ ۗ","for the battle"],["وَٱللَّهُ","And Allah"],["سَمِيعٌ","(is) All-Hearing"],["عَلِيمٌ","All-Knowing"]]],"415":["(Ketika) badal dari idz yang sebelumnya (dua golongan daripadamu bermaksud) yakni Bani Salamah dan Bani Haritsah yang merupakan dua sayap tentara (hendak mundur) karena takut berperang dan mengikuti langkah Abdullah bin Ubai pemimpin golongan munafik yang menarik diri dari peperangan bersama sahabat-sahabatnya, katanya, \"Apa gunanya kita membunuh diri dan anak-anak kita?\" Lalu katanya kepada Abu Jabir As-Salami yang memintanya agar membela Nabi dan diri mereka sendiri, \"Sekiranya kami pandai berperang, tentulah kami akan turut bersama kamu,\" maka Allah pun meneguhkan pendirian kedua golongan tadi hingga mereka tidak jadi menarik diri dari medan pertempuran (sedangkan Allah menjadi penolong bagi kedua golongan itu dan karena itu hendaklah kepada Allah orang-orang beriman bertawakal) hanya percaya kepada-Nya dan tidak kepada selain-Nya. Dan ketika mereka berhasil mengalahkan musuh, maka untuk mengingatkan mereka akan nikmat Allah turunlah ayat:",[["إِذْ","When"],["هَمَّت","inclined"],["طَّآئِفَتَانِ","two parties"],["مِنكُمْ","among you"],["أَن","that"],["تَفْشَلَا","they lost heart"],["وَٱللَّهُ","but Allah"],["وَلِيُّهُمَا ۗ","(was) their protector"],["وَعَلَى","And on"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","let put (their) trust"],["ٱلْمُؤْمِنُونَ","the believers"]]],"416":["(Sungguh, Allah telah menolong kamu di Badar) suatu tempat di antara Mekah dan Madinah (padahal kamu orang-orang yang lemah) disebabkan bilangan dan persenjataan yang sedikit (maka bertakwalah kepada Allah, supaya kamu menjadi orang-orang yang bersyukur) akan nikmat karunia-Nya",[["وَلَقَدْ","And certainly"],["نَصَرَكُمُ","helped you"],["ٱللَّهُ","Allah"],["بِبَدْرٍۢ","in Badr"],["وَأَنتُمْ","while you (were)"],["أَذِلَّةٌۭ ۖ","weak"],["فَٱتَّقُوا۟","So fear"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","so that you may"],["تَشْكُرُونَ","(be) grateful"]]],"417":["(Ketika) zharfu zaman bagi datangnya pertolongan (kamu mengatakan kepada orang-orang beriman) menjanjikan demi ketenteraman hati mereka (\"Tidakkah cukup bagi kamu jika kamu dibantu Tuhanmu dengan tiga ribu malaikat yang diturunkan.\") ada yang membaca munzaliina dan ada pula munazzaliina.",[["إِذْ","When"],["تَقُولُ","you said"],["لِلْمُؤْمِنِينَ","to the believers"],["أَلَن","Is it not"],["يَكْفِيَكُمْ","enough for you"],["أَن","that"],["يُمِدَّكُمْ","reinforces you"],["رَبُّكُم","your Lord"],["بِثَلَـٰثَةِ","with three"],["ءَالَـٰفٍۢ","thousand[s]"],["مِّنَ","[of]"],["ٱلْمَلَـٰٓئِكَةِ","[the] Angels"],["مُنزَلِينَ","[the ones] sent down"]]],"418":["(Ya) itu cukup bagi kamu. Dalam surah Al-Anfal disebutkan seribu yakni sebagai bantuan pertama kemudian menjadi tiga ribu lalu lima ribu sebagaimana firman Allah swt.: (Jika kamu bersabar) dalam menghadapi musuh (dan bertakwa) kepada Allah dalam menghindari pertikaian (dan mereka datang) yakni orang-orang musyrikin (pada ketika itu juga) buat menyerang kamu (maka Tuhanmu akan membantu kamu dengan lima ribu malaikat yang memakai tanda) ada yang membaca musawwimiina dan ada pula musawwamiina keduanya berarti memakai tanda. Sungguh mereka itu telah menunjukkan kesabaran sehingga Allah pun menepati janji-Nya yaitu dengan ikut sertanya pasukan malaikat di atas kuda-kuda belang dengan memakai serban berwarna kuning atau putih yang mereka lepaskan teruntai di atas bahu.",[["بَلَىٰٓ ۚ","Yes"],["إِن","if"],["تَصْبِرُوا۟","you are patient"],["وَتَتَّقُوا۟","and fear (Allah)"],["وَيَأْتُوكُم","and they come upon you"],["مِّن","[of]"],["فَوْرِهِمْ","suddenly"],["هَـٰذَا","[this]"],["يُمْدِدْكُمْ","will reinforce you"],["رَبُّكُم","your Lord"],["بِخَمْسَةِ","with five"],["ءَالَـٰفٍۢ","thousand[s]"],["مِّنَ","[of]"],["ٱلْمَلَـٰٓئِكَةِ","[the] Angels"],["مُسَوِّمِينَ","[the ones] having marks"]]],"419":["(Allah tidaklah menjadikannya) maksudnya pengiriman bala bantuan itu (melainkan sebagai berita gembira bagi kamu) dengan kemenangan (dan agar tenteram hatimu karenanya) jadi janganlah kamu cemas melihat banyaknya musuh dan sedikitnya bilanganmu. (Dan tidaklah kemenangan itu kecuali dari sisi Allah Yang Maha Tangguh lagi Maha Bijaksana) yang memberikannya kepada siapa yang dikehendaki-Nya dan bukan kepada yang banyak jumlah tentaranya.",[["وَمَا","And not"],["جَعَلَهُ","made it"],["ٱللَّهُ","Allah"],["إِلَّا","except"],["بُشْرَىٰ","(as) good news"],["لَكُمْ","for you"],["وَلِتَطْمَئِنَّ","and to reassure"],["قُلُوبُكُم","your hearts"],["بِهِۦ ۗ","with it"],["وَمَا","And (there is) no"],["ٱلنَّصْرُ","[the] victory"],["إِلَّا","except"],["مِنْ","from"],["عِندِ","[near]"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","the All-Mighty"],["ٱلْحَكِيمِ","the All-Wise"]]],"420":["(Yaitu untuk memotong) berkaitan dengan kemenanganmu itu dan maksudnya ialah membinasakan (segolongan orang-orang yang kafir) dengan terbunuh dan tertawan (atau untuk menjadikan mereka hina dina) disebabkan kekalahan (sehingga mereka kembali dengan tangan hampa) tidak memperoleh apa yang mereka harapkan. Ayat berikut ini turun ketika gigi depan Nabi saw. patah dan wajahnya berlumuran darah di waktu perang Uhud, sampai beliau bersabda, \"Bagaimana suatu kaum akan beroleh keberuntungan, jika mereka berani melumuri wajah Nabi mereka dengan darah!\"",[["لِيَقْطَعَ","That He may cut off"],["طَرَفًۭا","a part"],["مِّنَ","of"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieved"],["أَوْ","or"],["يَكْبِتَهُمْ","suppress them"],["فَيَنقَلِبُوا۟","so (that) they turn back"],["خَآئِبِينَ","disappointed"]]],"421":["(Tak ada sedikit pun hakmu untuk campur tangan dalam urusan mereka itu) tetapi semua itu urusan Allah, maka hendaklah kamu bersabar (apakah) artinya hingga (Allah menerima tobat mereka) dengan masuknya mereka ke dalam agama Islam (atau menyiksa mereka, karena sesungguhnya mereka orang-orang yang aniaya) disebabkan kekafiran mereka.",[["لَيْسَ","Not"],["لَكَ","for you"],["مِنَ","of"],["ٱلْأَمْرِ","the decision"],["شَىْءٌ","(of) anything"],["أَوْ","whether"],["يَتُوبَ","He turns"],["عَلَيْهِمْ","to them"],["أَوْ","or"],["يُعَذِّبَهُمْ","punishes them"],["فَإِنَّهُمْ","for indeed, they"],["ظَـٰلِمُونَ","(are) wrongdoers"]]],"422":["(Kepunyaan Allahlah apa yang ada di langit dan apa yang ada di bumi) baik sebagai milik maupun sebagai makhluk atau hamba-Nya (diampuni-Nya siapa yang dikehendaki-Nya) untuk diampuni (dan disiksa-Nya siapa yang dikehendaki) untuk disiksa (dan Allah Maha Pengampun) kekasih-kekasih-Nya (lagi Maha Penyayang) terhadap orang-orang yang taat kepada-Nya.",[["وَلِلَّهِ","And to Allah (belongs)"],["مَا","what"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and what"],["فِى","(is) in"],["ٱلْأَرْضِ ۚ","the earth"],["يَغْفِرُ","He forgives"],["لِمَن","[for] whom"],["يَشَآءُ","He wills"],["وَيُعَذِّبُ","and punishes"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَٱللَّهُ","And Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"423":["(Hai orang-orang yang beriman, janganlah kamu memakan riba dengan berlipat ganda) bacaannya ada yang memakai alif dan ada pula yang tidak, maksudnya ialah memberikan tambahan pada harta yang diutang yang ditangguhkan pembayarannya dari tempo yang telah ditetapkan (dan bertakwalah kamu kepada Allah) dengan menghindarinya (supaya kamu beroleh keberuntungan) atau hasil yang gemilang.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تَأْكُلُوا۟","eat"],["ٱلرِّبَوٰٓا۟","the usury"],["أَضْعَـٰفًۭا","doubled"],["مُّضَـٰعَفَةًۭ ۖ","multiplied"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","so that you may"],["تُفْلِحُونَ","(be) successful"]]],"424":["(Jagalah dirimu dari api neraka yang disediakan bagi orang-orang yang kafir) janganlah kamu sampai disiksa di dalamnya",[["وَٱتَّقُوا۟","And fear"],["ٱلنَّارَ","the Fire"],["ٱلَّتِىٓ","which"],["أُعِدَّتْ","is prepared"],["لِلْكَـٰفِرِينَ","for the disbelievers"]]],"425":["(Taatilah olehmu Allah dan Rasul, supaya kamu beroleh rahmat).",[["وَأَطِيعُوا۟","And obey"],["ٱللَّهَ","Allah"],["وَٱلرَّسُولَ","and the Messenger"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"426":["(Dan bersegeralah kamu) dengan atau tanpa wau (kepada keampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi) artinya seluas langit dan bumi bila keduanya disambung; sedangkan '`ardh' artinya ialah luas (yang disediakan bagi orang-orang yang bertakwa) kepada Allah dengan mengerjakan taat dan meninggalkan maksiat.",[["۞ وَسَارِعُوٓا۟","And hasten"],["إِلَىٰ","to"],["مَغْفِرَةٍۢ","forgiveness"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["وَجَنَّةٍ","and a Garden "],["عَرْضُهَا","its width"],["ٱلسَّمَـٰوَٰتُ","(is like that of) the heavens"],["وَٱلْأَرْضُ","and the earth"],["أُعِدَّتْ","prepared"],["لِلْمُتَّقِينَ","for the pious"]]],"427":["(Yaitu orang yang mengeluarkan nafkah) dalam menaati Allah (baik di waktu lapang maupun di waktu sempit dan yang dapat menahan amarahnya) hingga tidak melampiaskannya walaupun sebenarnya ia sanggup (dan yang memaafkan kesalahan manusia) yang melakukan keaniayaan kepadanya tanpa membalasnya (dan Allah menyukai orang-orang yang berbuat kebaikan) seperti pekerjaan-pekerjaan yang disebutkan itu dan akan memberi mereka balasan.",[["ٱلَّذِينَ","Those who"],["يُنفِقُونَ","spend"],["فِى","in"],["ٱلسَّرَّآءِ","[the] ease"],["وَٱلضَّرَّآءِ","and (in) the hardship"],["وَٱلْكَـٰظِمِينَ","and those who restrain"],["ٱلْغَيْظَ","the anger"],["وَٱلْعَافِينَ","and those who pardon"],["عَنِ","[from]"],["ٱلنَّاسِ ۗ","the people "],["وَٱللَّهُ","and Allah"],["يُحِبُّ","loves"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"428":["(Dan juga orang-orang yang apabila mereka berbuat kekejian) artinya dosa yang keji seperti perzinahan (atau menganiaya diri mereka sendiri) artinya melakukan dosa yang lebih ringan dari itu misalnya mencium (mereka ingat kepada Allah) maksudnya ingat akan ancaman-Nya (lalu memohon ampun terhadap dosa-dosa mereka dan siapakah) artinya tidak ada (yang dapat mengampuni dosa itu melainkan Allah. Dan mereka tidak meneruskan perbuatan mereka itu) menghentikannya sama sekali (sedangkan mereka mengetahui) bahwa apa yang mereka lakukan itu adalah perbuatan maksiat adanya.",[["وَٱلَّذِينَ","And those"],["إِذَا","when"],["فَعَلُوا۟","they did"],["فَـٰحِشَةً","immorality"],["أَوْ","or"],["ظَلَمُوٓا۟","wronged"],["أَنفُسَهُمْ","themselves "],["ذَكَرُوا۟","they remember"],["ٱللَّهَ","Allah"],["فَٱسْتَغْفَرُوا۟","then ask forgiveness"],["لِذُنُوبِهِمْ","for their sins "],["وَمَن","and who"],["يَغْفِرُ","(can) forgive"],["ٱلذُّنُوبَ","the sins"],["إِلَّا","except"],["ٱللَّهُ","Allah"],["وَلَمْ","And not"],["يُصِرُّوا۟","they persist"],["عَلَىٰ","on"],["مَا","what"],["فَعَلُوا۟","they did"],["وَهُمْ","while they"],["يَعْلَمُونَ","know"]]],"429":["(Mereka itu balasannya ialah ampunan dari Tuhan mereka dan surga yang di bawahnya mengalir anak-anak sungai, kekal mereka di dalamnya) menjadi hal artinya ditakdirkan kekal jika mereka beruntung memasukinya (dan itulah sebaik-baiknya pahala bagi orang yang beramal) artinya pahala bagi orang-orang yang mengerjakan perbuatan terpuji ini.",[["أُو۟لَـٰٓئِكَ","Those "],["جَزَآؤُهُم","their reward"],["مَّغْفِرَةٌۭ","(is) forgiveness"],["مِّن","from"],["رَّبِّهِمْ","their Lord"],["وَجَنَّـٰتٌۭ","and Gardens"],["تَجْرِى","flows"],["مِن","from"],["تَحْتِهَا","underneath it"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","abiding forever"],["فِيهَا ۚ","in it"],["وَنِعْمَ","And an excellent"],["أَجْرُ","reward"],["ٱلْعَـٰمِلِينَ","(for) the (righteous) workers"]]],"430":["Ayat ini diturunkan berkenaan dengan kekalahan dalam perang Uhud (Sesungguhnya telah berlalu sebelum kamu sunah-sunah) artinya cara-cara Allah menghadapi orang-orang kafir yaitu menangguhkan kebinasaan mereka, lalu menghancurkan mereka secara tiba-tiba (maka berjalanlah kamu) hai orang-orang beriman (di muka bumi, dan lihatlah betapa akibat orang-orang yang mendustakan) para rasul, artinya kesudahan nasib mereka berupa kebinasaan. Maka janganlah kamu bersedih hati atas kemenangan mereka, karena Aku hanyalah menangguhkan kebinasaan mereka itu hingga pada saatnya nanti.",[["قَدْ","Verily"],["خَلَتْ","passed"],["مِن","from"],["قَبْلِكُمْ","before you"],["سُنَنٌۭ","situations"],["فَسِيرُوا۟","then travel"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَٱنظُرُوا۟","and see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُكَذِّبِينَ","(of) the deniers"]]],"431":["(Ini) maksudnya Alquran ini (menjadi penerang bagi manusia) artinya semuanya (dan petunjuk) dari kesesatan (serta pelajaran bagi orang-orang yang bertakwa) di antara mereka.",[["هَـٰذَا","This"],["بَيَانٌۭ","(is) a declaration"],["لِّلنَّاسِ","for the people"],["وَهُدًۭى","and guidance"],["وَمَوْعِظَةٌۭ","and admonition"],["لِّلْمُتَّقِينَ","for the God-fearing"]]],"432":["(Janganlah kamu merasa lemah) dalam memerangi orang-orang kafir (dan jangan pula bersedih hati) atas sesuatu musibah yang menimpa dirimu (padahal kamu orang-orang yang tertinggi) hingga mampu mengalahkan mereka (jika kamu orang-orang yang beriman) maksudnya benar-benar beriman sedangkan yang menjadi jawab syarat ialah apa yang ditunjukkan oleh makna kalimat-kalimat yang sebelumnya.",[["وَلَا","And (do) not"],["تَهِنُوا۟","weaken"],["وَلَا","and (do) not"],["تَحْزَنُوا۟","grieve"],["وَأَنتُمُ","and you (will be)"],["ٱلْأَعْلَوْنَ","[the] superior"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"433":["(Jika kamu ditimpa) seperti pada perang Uhud (oleh luka-luka) qarh atau qurh, artinya ialah penderitaan disebabkan luka dan sebagainya (maka sesungguhnya kaum kafir itu pun telah ditimpa pula oleh luka yang serupa) di waktu perang Badar. (Dan hari-hari itu Kami pergilirkan) silih berganti (di antara manusia) misalnya sekarang masa kejayaan bagi satu golongan dan esok bagi golongan lainnya agar mereka sama-sama menarik pelajaran (dan supaya Allah mengetahui) secara lahiriah (orang-orang yang beriman) secara ikhlas dari yang tidak (dan supaya sebagian kamu dijadikan-Nya syuhada) artinya dimuliakan-Nya dengan mati syahid. (Dan Allah tidak menyukai orang-orang yang aniaya) yakni orang-orang kafir yang akan menerima hukuman daripada-Nya. Seumpama mereka diberi-Nya nikmat, itu hanyalah untuk mendekatkan mereka kepada siksa.",[["إِن","If"],["يَمْسَسْكُمْ","touched you"],["قَرْحٌۭ","a wound"],["فَقَدْ","so certainly"],["مَسَّ","(has) touched"],["ٱلْقَوْمَ","the people"],["قَرْحٌۭ","wound"],["مِّثْلُهُۥ ۚ","like it"],["وَتِلْكَ","And this"],["ٱلْأَيَّامُ","[the] days"],["نُدَاوِلُهَا","We alternate them"],["بَيْنَ","among"],["ٱلنَّاسِ","the people"],["وَلِيَعْلَمَ","[and] so that makes evident"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe[d]"],["وَيَتَّخِذَ","and take"],["مِنكُمْ","from you"],["شُهَدَآءَ ۗ","martyrs"],["وَٱللَّهُ","And Allah"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"434":["(Agar Allah menyucikan orang-orang yang beriman) artinya membersihkan mereka dari dosa dengan musibah yang menimpa diri mereka itu (serta membinasakan orang-orang yang kafir).",[["وَلِيُمَحِّصَ","And so that may purify"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَيَمْحَقَ","and destroy"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"435":["(Atau) artinya apakah (kamu mengira bahwa kamu akan masuk surga padahal belumlah diketahui oleh Allah orang-orang yang berjihad di antara kamu) yakni secara lahirnya (dan belum diketahui-Nya orang-orang yang sabar) dalam menghadapi kesusahan.",[["أَمْ","Or"],["حَسِبْتُمْ","do you think"],["أَن","that"],["تَدْخُلُوا۟","you will enter"],["ٱلْجَنَّةَ","Paradise"],["وَلَمَّا","while has not yet"],["يَعْلَمِ","made evident"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","those who"],["جَـٰهَدُوا۟","strove hard"],["مِنكُمْ","among you"],["وَيَعْلَمَ","and made evident"],["ٱلصَّـٰبِرِينَ","the steadfast"]]],"436":["(Sesungguhnya dulu kamu mengharapkan) asalnya tatamannauna lalu salah satu dari ta-nya dibuang (kematian sebelum kamu menemuinya) artinya kamu pernah mengatakan dulu, \"Wahai kiranya kami dapat menemui suatu hari seperti hari perang Badar agar kami menemui mati syahid sebagaimana dialami oleh kawan-kawan kami dulu.\" (Sekarang kamu telah melihatnya) maksudnya yang menjadi sebab dan asal usulnya yaitu peperangan itu sendiri (sedangkan kamu menyaksikannya) dapat merenungkannya bagaimana seharusnya lalu kenapa kamu dapat dikalahkan? Dan mengenai kekalahan itu turun ayat bahwa sebabnya ialah tatkala disebarkan berita bahwa Nabi saw. telah terbunuh sementara orang-orang munafik meneriakkan, \"Karena ia telah terbunuh maka kembalilah kalian kepada agama kalian!\"",[["وَلَقَدْ","And certainly"],["كُنتُمْ","you used to"],["تَمَنَّوْنَ","wish"],["ٱلْمَوْتَ","(for) death"],["مِن","from"],["قَبْلِ","before"],["أَن","[that]"],["تَلْقَوْهُ","you met it"],["فَقَدْ","then indeed"],["رَأَيْتُمُوهُ","you have seen it"],["وَأَنتُمْ","while you (were)"],["تَنظُرُونَ","looking on"]]],"437":["(Muhammad itu tidak lain hanyalah seorang rasul yang sebelumnya telah berlalu beberapa orang rasul. Apakah jika ia wafat atau terbunuh) seperti lainnya (kamu berbalik ke belakang) maksudnya kembali menjadi kafir. Kalimat akhir merupakan pertanyaan yang berarti sanggahan, artinya bukankah ia bukan sembahan kenapa kamu kembali? (Barang siapa yang berbalik ke belakang, murtad, maka tidaklah ia memberi mudarat kepada Allah sedikit pun) sebaliknya hanya memberi mudarat kepada dirinya sendiri (dan Allah akan memberi balasan kepada orang-orang yang bersyukur) terhadap nikmat-karunia-Nya.",[["وَمَا","And not"],["مُحَمَّدٌ","(is) Muhammad "],["إِلَّا","except"],["رَسُولٌۭ","a Messenger"],["قَدْ","certainly"],["خَلَتْ","passed away"],["مِن","from"],["قَبْلِهِ","before him"],["ٱلرُّسُلُ ۚ","[the] (other) Messengers"],["أَفَإِي۟ن","So if"],["مَّاتَ","he died"],["أَوْ","or"],["قُتِلَ","is slain"],["ٱنقَلَبْتُمْ","will you turn back"],["عَلَىٰٓ","on"],["أَعْقَـٰبِكُمْ ۚ","your heels"],["وَمَن","And whoever"],["يَنقَلِبْ","turns back"],["عَلَىٰ","on"],["عَقِبَيْهِ","his heels"],["فَلَن","then never"],["يَضُرَّ","will he harm"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا ۗ","(in) anything"],["وَسَيَجْزِى","And will reward"],["ٱللَّهُ","Allah"],["ٱلشَّـٰكِرِينَ","the grateful ones"]]],"438":["(Setiap diri tidaklah akan mati kecuali dengan izin Allah) artinya dengan kada daripada-Nya (sebagai ketentuan) mashdar artinya ketentuan yang telah ditetapkan oleh Allah (yang telah ditetapkan waktunya) hingga tidak dapat dimajukan atau diundurkan. Lalu kenapa kamu menderita kekalahan, padahal kekalahan itu tidak dapat menolak kematian dan ketabahan takkan dapat mengakhiri kehidupan. (Barang siapa yang menghendaki) dengan amalannya (pahala dunia) artinya balasannya (Kami berikan itu kepadanya) artinya bagiannya di dunia tetapi di akhirat ia tidak mendapat apa-apa. (Dan barang siapa menghendaki pahala akhirat Kami berikan pula kepadanya) artinya pahalanya (dan Kami akan memberi balasan kepada orang-orang yang bersyukur).",[["وَمَا","And not"],["كَانَ","is"],["لِنَفْسٍ","for a soul"],["أَن","that"],["تَمُوتَ","he dies"],["إِلَّا","except"],["بِإِذْنِ","by (the) permission"],["ٱللَّهِ","(of) Allah"],["كِتَـٰبًۭا","(at a) decree"],["مُّؤَجَّلًۭا ۗ","determined"],["وَمَن","And whoever"],["يُرِدْ","desires"],["ثَوَابَ","reward"],["ٱلدُّنْيَا","(of) the world "],["نُؤْتِهِۦ","We will give him"],["مِنْهَا","thereof"],["وَمَن","and whoever"],["يُرِدْ","desires"],["ثَوَابَ","reward"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["نُؤْتِهِۦ","We will give him"],["مِنْهَا ۚ","thereof"],["وَسَنَجْزِى","And We will reward"],["ٱلشَّـٰكِرِينَ","the grateful ones"]]],"439":["(Dan berapa banyaknya) 'ka-ayyin' sama artinya dengan 'kam' (nabi-nabi yang berperang) menurut satu qiraat 'qutila' yang berarti 'yang dibunuh'. Pelakunya ialah dhamir yang kembali kepada nabi (bersama mereka) menjadi khabar sedangkan mubtadanya ialah: (pengikut-pengikutnya yang amat banyak) yakni yang bertakwa (maka mereka tidak menjadi lemah) atau merasa takut (karena hal-hal yang menimpa mereka di jalan Allah) seperti mendapat luka dan terbunuhnya nabi-nabi dan para sahabat mereka (dan tidak menjadi lelah) menghadapi perjuangan (dan tidak pula menyerah) atau tunduk kepada musuh-musuh sebagaimana kamu lakukan ketika disiarkan orang berita bahwa Nabimu telah gugur. (Allah menyukai orang-orang yang sabar) dalam menerima bala hingga Allah berkenan memberikan imbalan kepadanya.",[["وَكَأَيِّن","And how many"],["مِّن","from"],["نَّبِىٍّۢ","a Prophet"],["قَـٰتَلَ","fought"],["مَعَهُۥ","with him"],["رِبِّيُّونَ","(were) religious scholars"],["كَثِيرٌۭ","many"],["فَمَا","But not"],["وَهَنُوا۟","they lost heart"],["لِمَآ","for what"],["أَصَابَهُمْ","befell them"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["وَمَا","and not"],["ضَعُفُوا۟","they weakened"],["وَمَا","and not"],["ٱسْتَكَانُوا۟ ۗ","they gave in"],["وَٱللَّهُ","And Allah"],["يُحِبُّ","loves"],["ٱلصَّـٰبِرِينَ","the patient ones"]]],"440":["(Tak ada ucapan mereka) yakni ketika Nabi mereka dibunuh yang mereka terima dengan penuh kesabaran dan ketabahan itu (melainkan dengan berdoa, \"Wahai Tuhan kami! Ampunilah dosa kami dan keterlaluan kami) artinya tindakan kami yang melanggar batas (dalam urusan kami) sebagai pengakuan bahwa musibah yang menimpa mereka itu ialah karena jeleknya perbuatan mereka yang berarti menghancurkan diri mereka sendiri (dan tetapkanlah hati kami) dengan kekuatan menghadapi perjuangan (serta tolonglah kami terhadap kaum yang kafir.\")",[["وَمَا","And not"],["كَانَ","were"],["قَوْلَهُمْ","their words"],["إِلَّآ","except"],["أَن","that"],["قَالُوا۟","they said"],["رَبَّنَا","Our Lord"],["ٱغْفِرْ","forgive"],["لَنَا","for us"],["ذُنُوبَنَا","our sins"],["وَإِسْرَافَنَا","and our excesses"],["فِىٓ","in"],["أَمْرِنَا","our affairs"],["وَثَبِّتْ","and make firm"],["أَقْدَامَنَا","our feet"],["وَٱنصُرْنَا","and give us victory"],["عَلَى","over"],["ٱلْقَوْمِ","[the people]"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"441":["(Maka Allah pun memberi mereka pahala di dunia) berupa kemenangan dan harta rampasan (dan pahala yang baik di akhirat) maksudnya surga. Pahala yang baik ialah anugerah yang melebihi dari selayaknya (dan Allah menyukai orang-orang yang berbuat kebaikan).",[["فَـَٔاتَىٰهُمُ","So gave them"],["ٱللَّهُ","Allah"],["ثَوَابَ","reward"],["ٱلدُّنْيَا","(in) the world"],["وَحُسْنَ","and good"],["ثَوَابِ","reward"],["ٱلْـَٔاخِرَةِ ۗ","(in) the Hereafter"],["وَٱللَّهُ","And Allah"],["يُحِبُّ","loves"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"442":["(Hai orang-orang yang beriman, jika kamu menaati orang-orang yang kafir) mengenai apa yang mereka perintahkan kepada kamu (tentulah mereka akan mengembalikan kamu ke belakang) maksudnya kepada kekafiran (hingga jadilah kamu orang-orang yang merugi).",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe"],["إِن","If"],["تُطِيعُوا۟","you obey"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["يَرُدُّوكُمْ","they will turn you back"],["عَلَىٰٓ","on"],["أَعْقَـٰبِكُمْ","your heels"],["فَتَنقَلِبُوا۟","then you will turn back"],["خَـٰسِرِينَ","(as) losers"]]],"443":["(Tetapi Allahlah yang menjadi pelindungmu) pembelamu (dan Dialah sebaik-baik pembela) maka patuhlah kamu kepada-Nya dan bukan kepada selain-Nya.",[["بَلِ","Nay"],["ٱللَّهُ","Allah"],["مَوْلَىٰكُمْ ۖ","(is) your Protector"],["وَهُوَ","and He"],["خَيْرُ","(is the) best"],["ٱلنَّـٰصِرِينَ","(of) the Helpers"]]],"444":["(Akan Kami masukkan ke dalam hati orang-orang kafir itu rasa takut) dibaca ru`b atau ru`ub. Setelah berangkat dari Uhud itu sebenarnya mereka bermaksud hendak kembali untuk membasmi kaum Muslimin tetapi tiba-tiba merasa ciut dan tidak jadi kembali (disebabkan mereka mempersekutukan Allah dengan sesuatu yang tidak diberi-Nya wewenang) sebagai alasan dalam penyembahan terhadap berhala (tempat tinggal mereka ialah neraka dan itulah seburuk-buruk tempat tinggal orang-orang yang aniaya) lagi kafir itu.",[["سَنُلْقِى","We will cast"],["فِى","in"],["قُلُوبِ","(the) hearts"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieve"],["ٱلرُّعْبَ","[the] terror"],["بِمَآ","because"],["أَشْرَكُوا۟","they associated partners"],["بِٱللَّهِ","with Allah"],["مَا","what"],["لَمْ","not"],["يُنَزِّلْ","He sent down"],["بِهِۦ","about it"],["سُلْطَـٰنًۭا ۖ","any authority"],["وَمَأْوَىٰهُمُ","and their refuge"],["ٱلنَّارُ ۚ","(will be) the Fire"],["وَبِئْسَ","and wretched"],["مَثْوَى","(is the) abode"],["ٱلظَّـٰلِمِينَ","[of] the wrongdoers"]]],"445":["(Dan sesungguhnya Allah telah memenuhi janji-Nya) kepadamu dengan memberikan kemenangan (ketika kamu membunuh mereka dengan izin-Nya) atau dengan kehendak-Nya (hingga saat kamu gagal) atau takut menghadapi peperangan (dan berselisih dalam urusan itu) yakni mengenai perintah Nabi saw. agar tetap bertahan di lereng bukit untuk memanah musuh di mana sebagian kamu mengatakan, \"Mari kita turun bukankah teman-teman kita sudah beroleh kemenangan?\" Sedangkan sebagian lagi berkata, \"Tidak, kita tidak boleh melanggar perintah Nabi saw.\" (dan kamu mendurhakai) perintahnya, lalu kamu tinggalkan markas demi mengharapkan harta rampasan (setelah diperlihatkan-Nya kepadamu) maksudnya oleh Allah (apa yang kamu sukai) yakni kemenangan. Mengenai jawab idzaa ditunjukkan oleh kalimat yang sebelumnya, artinya kamu terhalang beroleh kemenangan dari-Nya. (Di antaramu ada yang menghendaki dunia) lalu ditinggalkannya markas guna merebut harta rampasan (dan di antaramu ada yang menghendaki akhirat) maka ia tetap bertahan di tempat sampai ia gugur seperti Abdullah bin Jubair dan sahabat-sahabatnya. (Kemudian Allah memalingkan kamu) dihubungkan kepada jawaban idzaa yang diperkirakan berbunyi, \"Terpukul mundur karena menderita kekalahan\" (dari mereka) maksudnya orang-orang kafir (untuk mencoba kamu) artinya menguji mana-mana yang ikhlas di antaramu dari yang bukan. (Sesungguhnya Allah telah memaafkan kamu) atas kesalahan yang telah kamu lakukan (dan Allah mempunyai karunia terhadap orang-orang yang beriman) dengan memaafkan dan mengampuni mereka.",[["وَلَقَدْ","And certainly"],["صَدَقَكُمُ","fulfilled to you"],["ٱللَّهُ","Allah"],["وَعْدَهُۥٓ","His promise"],["إِذْ","when"],["تَحُسُّونَهُم","you were killing them"],["بِإِذْنِهِۦ ۖ","by His permission"],["حَتَّىٰٓ","until"],["إِذَا","when"],["فَشِلْتُمْ","you lost courage"],["وَتَنَـٰزَعْتُمْ","and you fell into dispute"],["فِى","concerning"],["ٱلْأَمْرِ","the order"],["وَعَصَيْتُم","and you disobeyed"],["مِّنۢ","from"],["بَعْدِ","after"],["مَآ","[what]"],["أَرَىٰكُم","He (had) shown you"],["مَّا","what"],["تُحِبُّونَ ۚ","you love"],["مِنكُم","Among you"],["مَّن","(are some) who"],["يُرِيدُ","desire"],["ٱلدُّنْيَا","the world"],["وَمِنكُم","and among you"],["مَّن","(are some) who"],["يُرِيدُ","desire"],["ٱلْـَٔاخِرَةَ ۚ","the Hereafter"],["ثُمَّ","Then"],["صَرَفَكُمْ","He diverted you"],["عَنْهُمْ","from them"],["لِيَبْتَلِيَكُمْ ۖ","so that He may test you"],["وَلَقَدْ","And surely"],["عَفَا","He forgave"],["عَنكُمْ ۗ","you"],["وَٱللَّهُ","And Allah"],["ذُو","(is the) Possessor"],["فَضْلٍ","(of) Bounty"],["عَلَى","for"],["ٱلْمُؤْمِنِينَ","the believers"]]],"446":["(Ingatlah ketika kamu melarikan diri) dalam peperangan itu (dan tidak menoleh kepada seorang pun, sedang Rasul memanggil kamu dari belakangmu) seraya bersabda, \"Mari ke sini hai hamba-hamba Allah, marilah datang kepadaku!\" (Karena itu Allah menimpakan padamu kesedihan di atas kesedihan) yang kamu timpakan kepada Rasulullah dengan melanggar perintahnya. Ada pula yang mengatakan 'ba' itu berarti '`alaa' hingga maknanya ialah 'berlipat ganda', yaitu kesedihan di balik kesedihan karena luputnya harta rampasan (supaya kamu tidak) berkaitan dengan Allah 'memaafkan' atau menimpakan pada kalian (berduka cita terhadap apa yang luput dari kamu) yakni harta rampasan (begitu pula terhadap apa yang telah menimpamu) berupa pembunuhannya dan kekalahan (Allah Maha Mengetahui apa yang kamu kerjakan.)",[["۞ إِذْ","When"],["تُصْعِدُونَ","you were running uphill"],["وَلَا","and not"],["تَلْوُۥنَ","casting a glance"],["عَلَىٰٓ","on"],["أَحَدٍۢ","anyone"],["وَٱلرَّسُولُ","while the Messenger"],["يَدْعُوكُمْ","was calling you"],["فِىٓ","[in]"],["أُخْرَىٰكُمْ","(from) behind you"],["فَأَثَـٰبَكُمْ","So (He) repaid you"],["غَمًّۢا","(with) distress"],["بِغَمٍّۢ","on distress"],["لِّكَيْلَا","so that not"],["تَحْزَنُوا۟","you grieve"],["عَلَىٰ","over"],["مَا","what"],["فَاتَكُمْ","escaped you"],["وَلَا","and not"],["مَآ","what"],["أَصَـٰبَكُمْ ۗ","(had) befallen you"],["وَٱللَّهُ","And Allah"],["خَبِيرٌۢ","(is) All-Aware"],["بِمَا","of what"],["تَعْمَلُونَ","you do"]]],"447":["(Kemudian Allah menurunkan kepada kamu setelah kesedihan itu keamanan berupa kantuk) menjadi badal (yang meliputi) ada yang membaca dengan ya dan ada pula dengan ta (segolongan dari kamu) yakni orang-orang beriman; mereka tertidur lelap di balik tameng sehingga pedang-pedang pun tergelincir dan jatuh ke sisi mereka (sedangkan segolongan lagi telah dicemaskan oleh diri mereka sendiri) maksudnya mereka merasa cemas memikirkan nasib mereka hingga mereka tak ada kemauan selain menyelamatkan diri tanpa mempedulikan Nabi saw. dan para sahabatnya. Mereka tidak dapat tidur dan mereka adalah orang-orang munafik. (Mereka menyangka yang tidak benar terhadap Allah) maksudnya seperti sangkaan (jahiliah) yang berkeyakinan bahwa Nabi itu benar-benar telah terbunuh atau kalau tidak, maka ia takkan dapat dikalahkan. (Kata mereka, \"Apakah) maksudnya tak ada (bagi kita terhadap urusan ini) maksudnya mengenai kemenangan yang telah Kami janjikan itu (dari) merupakan tambahan (sesuatu.\"). (Katakanlah) kepada mereka (\"Sesungguhnya urusan ini seluruhnya) manshub sebagai taukid dapat pula marfu` sebagai mubtada sedangkan khabarnya ialah: (bagi Allah.\") maksudnya ketentuan berada di tangan-Nya. Ia berbuat apa yang dikehendaki-Nya (Mereka menyembunyikan dalam hati mereka apa yang tidak mereka terangkan kepadamu, maka mereka mengatakan) ini menjadi keterangan bagi 'apa' yang sebelumnya (\"Sekiranya bagi kami terhadap urusan ini ada sesuatu tidaklah kami terbunuh di sini) maksudnya jika kita mempunyai campur tangan dalam urusan ini kita dapat saja tidak keluar sehingga tidak terbunuh tetapi apa daya kita karena kita ini dipaksa keluar.\" (Katakanlah) kepada mereka (\"Sekiranya kamu berada di rumahmu) sedangkan di antaramu ada orang yang telah ditetapkan Allah akan menemui ajalnya (niscaya orang-orang yang telah ditakdirkan akan terbunuh itu akan keluar juga ke tempat pembunuhan mereka.\") sehingga mereka akan mati terbunuh, dan tidak akan tertolong oleh ikhtiar atau usaha mereka itu karena kada Allah tetap berlaku tanpa sesuatu pun dapat menolaknya. (Dan) hal itu dilakukan-Nya (agar Allah menguji apa yang terdapat dalam dadamu) dalam hatimu berupa keikhlasan atau kemunafikan (dan untuk membersihkan isi hatimu. Dan Allah Maha Mengetahui akan sisi hati) semua itu tak ada yang tersembunyi bagi-Nya tetapi maksud-Nya agar dengan ujian itu tampaklah pula bagi manusia keikhlasan dan kemunafikan di antara kalian.",[["ثُمَّ","Then"],["أَنزَلَ","He sent down"],["عَلَيْكُم","upon you"],["مِّنۢ","from"],["بَعْدِ","after"],["ٱلْغَمِّ","the distress"],["أَمَنَةًۭ","security "],["نُّعَاسًۭا","slumber"],["يَغْشَىٰ","overcoming"],["طَآئِفَةًۭ","a group"],["مِّنكُمْ ۖ","of you"],["وَطَآئِفَةٌۭ","while a group"],["قَدْ","certainly"],["أَهَمَّتْهُمْ","worried [them]"],["أَنفُسُهُمْ","(about) themselves"],["يَظُنُّونَ","thinking"],["بِٱللَّهِ","about Allah"],["غَيْرَ","other than"],["ٱلْحَقِّ","the truth "],["ظَنَّ","(the) thought"],["ٱلْجَـٰهِلِيَّةِ ۖ","(of) [the] ignorance"],["يَقُولُونَ","saying"],["هَل","Is (there)"],["لَّنَا","for us"],["مِنَ","from"],["ٱلْأَمْرِ","the matter"],["مِن","any"],["شَىْءٍۢ ۗ","thing"],["قُلْ","Say"],["إِنَّ","Indeed"],["ٱلْأَمْرَ","the matter"],["كُلَّهُۥ","all (of) it"],["لِلَّهِ ۗ","(is) for Allah"],["يُخْفُونَ","They hide"],["فِىٓ","in"],["أَنفُسِهِم","themselves"],["مَّا","what"],["لَا","not"],["يُبْدُونَ","they reveal"],["لَكَ ۖ","to you"],["يَقُولُونَ","They say"],["لَوْ","If"],["كَانَ","was"],["لَنَا","for us"],["مِنَ","from"],["ٱلْأَمْرِ","the matter"],["شَىْءٌۭ","anything"],["مَّا","not"],["قُتِلْنَا","we would have been killed"],["هَـٰهُنَا ۗ","here"],["قُل","Say"],["لَّوْ","If"],["كُنتُمْ","you were"],["فِى","in"],["بُيُوتِكُمْ","your houses"],["لَبَرَزَ","surely (would have) come out"],["ٱلَّذِينَ","those who "],["كُتِبَ","was decreed"],["عَلَيْهِمُ","upon them"],["ٱلْقَتْلُ","[the] death"],["إِلَىٰ","towards"],["مَضَاجِعِهِمْ ۖ","their places of death"],["وَلِيَبْتَلِىَ","And that might test"],["ٱللَّهُ","Allah"],["مَا","what"],["فِى","(is) in"],["صُدُورِكُمْ","your breasts"],["وَلِيُمَحِّصَ","and that He may purge"],["مَا","what"],["فِى","(is) in"],["قُلُوبِكُمْ ۗ","your hearts"],["وَٱللَّهُ","And Allah"],["عَلِيمٌۢ","(is) All-Aware"],["بِذَاتِ","of what"],["ٱلصُّدُورِ","(is in) the breasts"]]],"448":["(Sesungguhnya orang-orang yang berpaling di antara kamu) dari peperangan (di saat bertemunya dua pasukan) yaitu pasukan kaum Muslimin dan pasukan orang-orang kafir di Uhud. Yang dituju ialah pasukan Muslimin itu kecuali dua belas orang (sesungguhnya mereka digelincirkan oleh setan) dengan waswas atau tipu dayanya (disebabkan sebagian apa yang mereka perbuat) berupa dosa yaitu melanggar perintah Nabi saw. (dan sesungguhnya Allah telah memberi maaf kepada mereka. Sesungguhnya Allah Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyantun) sehingga menangguhkan siksa dari orang-orang durhaka.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["تَوَلَّوْا۟","turned back"],["مِنكُمْ","among you"],["يَوْمَ","(on the) day"],["ٱلْتَقَى","met"],["ٱلْجَمْعَانِ","the two hosts "],["إِنَّمَا","only"],["ٱسْتَزَلَّهُمُ","made them slip"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["بِبَعْضِ","for some"],["مَا","(of) what"],["كَسَبُوا۟ ۖ","they (had) earned"],["وَلَقَدْ","And surely"],["عَفَا","forgave"],["ٱللَّهُ","Allah"],["عَنْهُمْ ۗ","[on] them"],["إِنَّ","indeed"],["ٱللَّهَ","Allah"],["غَفُورٌ","(is) Oft-Forgiving"],["حَلِيمٌۭ","All-Forbearing"]]],"449":["(Hai orang-orang yang beriman! Janganlah kamu seperti orang-orang kafir) maksudnya orang-orang munafik (yang mengatakan kepada kawan-kawan mereka) mengenai keadaan mereka (apabila mereka bepergian di muka bumi) lalu mati (atau mereka berperang) lalu terbunuh (\"Sekiranya mereka berada bersama kita tidaklah mereka akan mati dan tidak pula terbunuh.\") maksudnya janganlah kamu berkata seperti demikian. (Allah menjadikan demikian itu) sebagai akibat dari ucapan mereka tadi (suatu penyesalan dalam hati mereka. Allah menghidupkan dan mematikan) hingga tinggalnya seseorang di rumahnya sama sekali tidak menghalangi kematiannya (dan terhadap apa yang kamu kerjakan) dengan memakai ta atau ya (Maha Melihat) maka kelak Dia akan membalaskannya kepada kalian.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe[d]"],["لَا","(Do) not"],["تَكُونُوا۟","be"],["كَٱلَّذِينَ","like those who"],["كَفَرُوا۟","disbelieved"],["وَقَالُوا۟","and they said"],["لِإِخْوَٰنِهِمْ","about their brothers"],["إِذَا","when"],["ضَرَبُوا۟","they traveled"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["أَوْ","or"],["كَانُوا۟","they were"],["غُزًّۭى","fighting"],["لَّوْ","If"],["كَانُوا۟","they had been"],["عِندَنَا","with us"],["مَا","not"],["مَاتُوا۟","they (would have) died"],["وَمَا","and not"],["قُتِلُوا۟","they (would have) been killed"],["لِيَجْعَلَ","So makes"],["ٱللَّهُ","Allah"],["ذَٰلِكَ","that"],["حَسْرَةًۭ","a regret"],["فِى","in"],["قُلُوبِهِمْ ۗ","their hearts"],["وَٱللَّهُ","And Allah"],["يُحْىِۦ","gives life"],["وَيُمِيتُ ۗ","and causes death"],["وَٱللَّهُ","and Allah"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["بَصِيرٌۭ","(is) All-Seer"]]],"450":["(Sungguh sekiranya) lam menunjukkan sumpah (kamu dibunuh di jalan Allah) maksudnya dalam berjihad (atau meninggal) dibaca muttum atau mittum berasal dari maata-yamuutu; artinya didatangi oleh kematian di dalam berjihad (maka ampunan) yang kamu peroleh (dari Allah) terhadap dosa-dosamu (dan rahmat) daripada-Nya bagi kamu atas demikian itu. Lam serta kalimat yang dimasukinya menjadi jawab qasam di samping menjadi mubtada yang khabarnya ialah: (benar-benar lebih baik dari apa yang mereka kumpulkan) dari harta dunia; memakai ya atau ta.",[["وَلَئِن","And if"],["قُتِلْتُمْ","you are killed"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["أَوْ","or"],["مُتُّمْ","die[d] "],["لَمَغْفِرَةٌۭ","certainly forgiveness"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["وَرَحْمَةٌ","and Mercy"],["خَيْرٌۭ","(are) better"],["مِّمَّا","than what"],["يَجْمَعُونَ","they accumulate"]]],"451":["(Sungguh sekiranya) lam berarti sumpah (kamu meninggal) dibaca muttum atau mittum (atau terbunuh) dalam peperangan atau lainnya (maka hanya kepada Allahlah) dan bukan kepada selain-Nya (kamu akan dihimpun) di akhirat di mana amal perbuatanmu akan dibalas-Nya.",[["وَلَئِن","And if"],["مُّتُّمْ","you die"],["أَوْ","or"],["قُتِلْتُمْ","are killed"],["لَإِلَى","surely to"],["ٱللَّهِ","Allah"],["تُحْشَرُونَ","you will be gathered"]]],"452":["(Maka berkat) ma merupakan tambahan (rahmat dari Allah kamu menjadi lemah lembut) hai Muhammad (kepada mereka) sehingga kamu hadapi pelanggaran mereka terhadap perintahmu itu dengan sikap lunak (dan sekiranya kamu bersikap keras) artinya akhlakmu jelek tidak terpuji (dan berhati kasar) hingga kamu mengambil tindakan keras terhadap mereka (tentulah mereka akan menjauhkan diri dari sekelilingmu, maka maafkanlah mereka) atas kesalahan yang mereka perbuat (dan mintakanlah ampunan bagi mereka) atas kesalahan-kesalahan itu hingga Kuampuni (serta berundinglah dengan mereka) artinya mintalah pendapat atau buah pikiran mereka (mengenai urusan itu) yakni urusan peperangan dan lain-lain demi mengambil hati mereka, dan agar umat meniru sunah dan jejak langkahmu, maka Rasulullah saw. banyak bermusyawarah dengan mereka. (Kemudian apabila kamu telah berketetapan hati) untuk melaksanakan apa yang kamu kehendaki setelah bermusyawarah itu (maka bertawakallah kepada Allah) artinya percayalah kepada-Nya. (Sesungguhnya Allah menyukai orang-orang yang bertawakal) kepada-Nya.",[["فَبِمَا","So because"],["رَحْمَةٍۢ","(of) Mercy"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["لِنتَ","you dealt gently"],["لَهُمْ ۖ","with them"],["وَلَوْ","And if"],["كُنتَ","you had been"],["فَظًّا","rude"],["غَلِيظَ","(and) harsh"],["ٱلْقَلْبِ","(at) [the] heart"],["لَٱنفَضُّوا۟","surely they (would have) dispersed"],["مِنْ","from"],["حَوْلِكَ ۖ","around you"],["فَٱعْفُ","Then pardon"],["عَنْهُمْ","[from] them"],["وَٱسْتَغْفِرْ","and ask forgiveness"],["لَهُمْ","for them"],["وَشَاوِرْهُمْ","and consult them"],["فِى","in"],["ٱلْأَمْرِ ۖ","the matter"],["فَإِذَا","Then when"],["عَزَمْتَ","you have decided"],["فَتَوَكَّلْ","then put trust"],["عَلَى","on"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يُحِبُّ","loves"],["ٱلْمُتَوَكِّلِينَ","the ones who put trust (in Him)"]]],"453":["(Jika Allah menolong kamu) terhadap musuhmu seperti di perang Badar (maka tak ada orang yang akan mengalahkan kamu, sebaliknya jika Dia membiarkan kamu) tanpa memberikan pertolongan seperti waktu perang Uhud (maka siapakah lagi yang dapat menolongmu setelah itu) artinya setelah kekalahan itu, maksudnya tak ada lagi. (Hanya kepada Allahlah) bukan kepada lain-Nya (orang-orang beriman itu harus bertawakal). Ayat berikut ini diturunkan ketika hilangnya sehelai permadani merah di waktu perang Uhud lalu sebagian orang mengatakan barangkali Nabilah yang mengambilnya:",[["إِن","If"],["يَنصُرْكُمُ","helps you"],["ٱللَّهُ","Allah"],["فَلَا","then not"],["غَالِبَ","(can) overcome"],["لَكُمْ ۖ","[for] you"],["وَإِن","and if"],["يَخْذُلْكُمْ","He forsakes you"],["فَمَن","then who"],["ذَا","(is)"],["ٱلَّذِى","the one who"],["يَنصُرُكُم","can help you"],["مِّنۢ","from"],["بَعْدِهِۦ ۗ","after Him"],["وَعَلَى","And on"],["ٱللَّهِ","Allah "],["فَلْيَتَوَكَّلِ","let put (their) trust"],["ٱلْمُؤْمِنُونَ","the believers"]]],"454":["(Tidaklah mungkin) atau patut (bagi seorang Nabi itu akan berkhianat dalam urusan harta rampasan perang) maka janganlah kamu menyangka hal yang demikian itu! Menurut satu qiraat dibaca 'yughalla' yang berarti dinisbatkan kepada pengkhianatan. (Barang siapa yang berkhianat dalam urusan harta rampasan perang itu, maka ia akan datang pada hari kiamat membawa barang yang dikhianatkannya itu) dengan memikulnya di atas pundaknya (kemudian setiap diri akan diberi balasan) baik yang berkhianat maupun yang tidak berkhianat (atas apa yang dikerjakannya sedangkan mereka tidaklah dianiaya) sedikit pun juga.",[["وَمَا","And not"],["كَانَ","is"],["لِنَبِىٍّ","for a Prophet"],["أَن","that"],["يَغُلَّ ۚ","he defrauds"],["وَمَن","And whoever"],["يَغْلُلْ","defrauds"],["يَأْتِ","will bring"],["بِمَا","what"],["غَلَّ","he had defrauded"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) Resurrection"],["ثُمَّ","Then"],["تُوَفَّىٰ","is repaid in full"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["مَّا","what"],["كَسَبَتْ","it earned"],["وَهُمْ","and they"],["لَا","(will) not"],["يُظْلَمُونَ","be wronged"]]],"455":["(Apakah orang yang mengikuti keridaan Allah) lalu ia taat dan tak berkhianat dalam soal rampasan perang (akan sama dengan orang yang kembali dengan kemurkaan dari Allah) karena perbuatan maksiat dan kecurangannya? (Tempatnya ialah neraka Jahanam dan itulah seburuk-buruk tempat kembali) jawabannya tentu saja tidak sama.",[["أَفَمَنِ","So is (the one) who"],["ٱتَّبَعَ","pursues"],["رِضْوَٰنَ","(the) pleasure"],["ٱللَّهِ","(of) Allah"],["كَمَنۢ","like (the one) who"],["بَآءَ","draws"],["بِسَخَطٍۢ","on (himself) wrath"],["مِّنَ","of"],["ٱللَّهِ","Allah"],["وَمَأْوَىٰهُ","and his abode"],["جَهَنَّمُ ۚ","(is) hell"],["وَبِئْسَ","and wretched"],["ٱلْمَصِيرُ","(is) the destination"]]],"456":["(Mereka itu bertingkat-tingkat) maksudnya mempunyai tingkat masing-masing (di sisi Allah) artinya mempunyai kedudukan yang berbeda-beda. Maka orang yang mengikuti keridaan-Nya akan beroleh pahala atau surga sedangkan yang membawa amarah murka-Nya akan mendapat siksa atau neraka (dan Allah Maha Melihat apa yang mereka kerjakan) hingga akan mendapat balasan daripada-Nya.",[["هُمْ","They"],["دَرَجَـٰتٌ","(are in varying) degrees"],["عِندَ","near"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","and Allah"],["بَصِيرٌۢ","(is) All-Seer"],["بِمَا","of what"],["يَعْمَلُونَ","they do"]]],"457":["(Sesungguhnya Allah telah memberi karunia kepada orang-orang beriman ketika Dia mengirim kepada mereka seorang rasul dari kalangan mereka sendiri) maksudnya seorang Arab seperti mereka untuk mengawasi dan memberi pengertian, jadi bukan dari kalangan malaikat dan tidak pula dari bangsa asing (yang membacakan kepada mereka ayat-ayat-Nya) yakni Alquran (dan menyucikan mereka) membersihkan mereka dari dosa (serta mengajarkan kepada mereka Alkitab) yakni Alquran (dan hikmah) yakni sunah (dan sesungguhnya mereka) ditakhfifkan dari wainnahum (adalah sebelumnya) yakni sebelum kebangkitannya (benar-benar dalam kesesatan yang nyata) atau jelas.",[["لَقَدْ","Certainly"],["مَنَّ","bestowed a Favor"],["ٱللَّهُ","Allah"],["عَلَى","upon"],["ٱلْمُؤْمِنِينَ","the believers"],["إِذْ","as"],["بَعَثَ","He raised"],["فِيهِمْ","among them"],["رَسُولًۭا","a Messenger"],["مِّنْ","from"],["أَنفُسِهِمْ","themselves"],["يَتْلُوا۟","reciting"],["عَلَيْهِمْ","to them"],["ءَايَـٰتِهِۦ","His Verses"],["وَيُزَكِّيهِمْ","and purifying them"],["وَيُعَلِّمُهُمُ","and teaching them"],["ٱلْكِتَـٰبَ","the Book"],["وَٱلْحِكْمَةَ","and the wisdom"],["وَإِن","although"],["كَانُوا۟","they were"],["مِن","from"],["قَبْلُ","before (that)"],["لَفِى","certainly in"],["ضَلَـٰلٍۢ","(the) error"],["مُّبِينٍ","clear"]]],"458":["(Mengapa ketika kamu ditimpa musibah) yaitu di Uhud dengan gugurnya 70 orang di antara kamu (padahal kamu telah menimpakan kekalahan dua kali lipat kepada musuh-musuhmu) yakni di Badar dengan membunuh 70 orang dan menawan 70 di antara mereka (kamu berkata) dengan keheran-heranan (\"Dari mana datangnya ini?\") maksudnya kekalahan ini padahal kita adalah orang-orang muslim dan Rasulullah berada bersama kita. Kalimat terakhir merupakan pertanyaan yang berarti sanggahan. (Katakanlah) kepada mereka (\"Itu dari dirimu sendiri) karena kamu meninggalkan markas sehingga mengalami kegagalan. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu.\") dan daripada-Nyalah datang kemenangan atau terhalangnya kemenangan itu; dan kamu mendapat balasan daripada-Nya disebabkan pelanggaran terhadap perintah Rasul-Nya.",[["أَوَلَمَّآ","Or when"],["أَصَـٰبَتْكُم","struck you"],["مُّصِيبَةٌۭ","disaster"],["قَدْ","surely"],["أَصَبْتُم","you (had) struck (them)"],["مِّثْلَيْهَا","twice of it"],["قُلْتُمْ","you said"],["أَنَّىٰ","From where"],["هَـٰذَا ۖ","(is) this"],["قُلْ","Say"],["هُوَ","It"],["مِنْ","(is)"],["عِندِ","from"],["أَنفُسِكُمْ ۗ","yourselves"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","All-Powerful"]]],"459":["(Apa yang menimpa kamu di hari bertemunya dua pasukan) yakni di Uhud (maka adalah dengan izin Allah) atau kehendak-Nya (dan supaya diketahui-Nya) secara nyata (orang-orang yang beriman) yang benar-benar beriman.",[["وَمَآ","And what"],["أَصَـٰبَكُمْ","struck you"],["يَوْمَ","(on the) day"],["ٱلْتَقَى","(when) met"],["ٱلْجَمْعَانِ","the two hosts"],["فَبِإِذْنِ","(was) by (the) permission"],["ٱللَّهِ","(of) Allah"],["وَلِيَعْلَمَ","and that He (might) make evident"],["ٱلْمُؤْمِنِينَ","the believers"]]],"460":["(Dan supaya diketahui-Nya orang-orang yang munafik dan) orang-orang yang (dikatakan kepada mereka) ketika mereka berpaling dari peperangan, yaitu Abdullah bin Ubai dan anak buahnya (\"Marilah kita berperang di jalan Allah) dengan musuh-musuh-Nya (atau usirlah mereka\") dari kami dengan memperbanyak anggotamu jika kamu tidak hendak berperang! (Jawab mereka, \"Sekiranya kami tahu) maksudnya pandai (berperang, tentulah kami akan mengikuti kamu\") firman Allah mendustakan mereka, (\"Pada hari itu mereka lebih dekat kepada kekafiran daripada keimanan) dengan sikap mereka yang terang-terangan mengkhianati kaum Muslimin sedangkan sebelumnya mereka pada lahirnya lebih dekat kepada keimanan. (Mereka mengatakan dengan mulut mereka apa yang tidak terdapat di dalam hati mereka) karena seandainya mereka pandai berperang, mereka juga tidak akan mengikutimu! (Dan Allah lebih mengetahui apa-apa yang mereka sembunyikan\") berupa kemunafikan.",[["وَلِيَعْلَمَ","And that He (might) make evident"],["ٱلَّذِينَ","those who"],["نَافَقُوا۟ ۚ","(are) hypocrites"],["وَقِيلَ","And it was said"],["لَهُمْ","to them"],["تَعَالَوْا۟","Come"],["قَـٰتِلُوا۟","fight"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["أَوِ","or"],["ٱدْفَعُوا۟ ۖ","defend"],["قَالُوا۟","They said"],["لَوْ","If"],["نَعْلَمُ","we knew"],["قِتَالًۭا","fighting"],["لَّٱتَّبَعْنَـٰكُمْ ۗ","certainly we (would have) followed you"],["هُمْ","They "],["لِلْكُفْرِ","to disbelief"],["يَوْمَئِذٍ","that day"],["أَقْرَبُ","(were) nearer"],["مِنْهُمْ","than [them]"],["لِلْإِيمَـٰنِ ۚ","to the faith"],["يَقُولُونَ","saying"],["بِأَفْوَٰهِهِم","with their mouths"],["مَّا","what"],["لَيْسَ","was not"],["فِى","in"],["قُلُوبِهِمْ ۗ","their hearts"],["وَٱللَّهُ","And Allah"],["أَعْلَمُ","(is) Most Knowing"],["بِمَا","of what"],["يَكْتُمُونَ","they conceal"]]],"461":["(Yakni orang-orang) menjadi badal atau sifat bagi 'orang-orang' yang sebelumnya (yang mengatakan kepada saudara-saudara mereka) seagama (dan) sesungguhnya (mereka tidak ikut) berperang (\"Sekiranya mereka mengikuti kita) maksudnya orang-orang yang gugur di perang Uhud itu (tentulah mereka tidak akan terbunuh!\" Katakanlah) kepada mereka (\"Hindarkanlah) tolaklah (kematian dari dirimu jika kamu orang-orang yang benar.\") bahwa tidak ikut berperang itu dapat menghindarkan kematian. Ayat berikut turun mengenai syuhada atau orang-orang yang mati syahid",[["ٱلَّذِينَ","Those who"],["قَالُوا۟","said"],["لِإِخْوَٰنِهِمْ","about their brothers"],["وَقَعَدُوا۟","while they sat"],["لَوْ","If"],["أَطَاعُونَا","they (had) obeyed us"],["مَا","not"],["قُتِلُوا۟ ۗ","they would have been killed"],["قُلْ","Say"],["فَٱدْرَءُوا۟","Then avert"],["عَنْ","from"],["أَنفُسِكُمُ","yourselves"],["ٱلْمَوْتَ","[the] death"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"462":["(Janganlah kamu kira bahwa orang-orang yang gugur) dengan takhfif atau pakai tasydid (di jalan Allah) maksudnya demi agama-Nya (mati, tetapi) mereka itu (hidup di sisi Tuhan mereka). Roh-roh mereka berada dalam kantong burung-burung hijau yang beterbangan dalam surga ke mana saja mereka kehendaki sebagaimana tersebut dalam sebuah hadis (dengan mendapat rezeki) yaitu dengan memakan buah-buahan surga.",[["وَلَا","And (do) not"],["تَحْسَبَنَّ","think"],["ٱلَّذِينَ","(of) those who"],["قُتِلُوا۟","are killed"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["أَمْوَٰتًۢا ۚ","(as) dead"],["بَلْ","Nay"],["أَحْيَآءٌ","They are alive"],["عِندَ","near"],["رَبِّهِمْ","their Lord"],["يُرْزَقُونَ","they are given provision"]]],"463":["(Mereka riang gembira) menjadi hal dari kata ganti yang terdapat pada yurzaquuna (dengan karunia yang diberikan Allah kepada mereka, dan) mereka (bersenang hati terhadap orang-orang yang masih belum menyusul di belakang mereka) yakni dari saudara-saudara mereka orang-orang beriman dan yang menjadi badal bagi 'alladziina' (bahwa) artinya disebabkan karena (tak ada kekhawatiran terhadap mereka, dan tidak pula mereka akan berdukacita) di akhirat kelak. Maksudnya mereka bersenang hati pula karena teman-teman mereka yang akan menyusul di belakang tak perlu dikhawatirkan nasib dan keamanan mereka.",[["فَرِحِينَ","Rejoicing"],["بِمَآ","in what"],["ءَاتَىٰهُمُ","bestowed them"],["ٱللَّهُ","Allah"],["مِن","of"],["فَضْلِهِۦ","His Bounty"],["وَيَسْتَبْشِرُونَ","and they receive good tidings"],["بِٱلَّذِينَ","about those who"],["لَمْ","(have) not"],["يَلْحَقُوا۟","yet joined"],["بِهِم","[with] them"],["مِّنْ","[from]"],["خَلْفِهِمْ","(but are) left behind "],["أَلَّا","that (there will be) no"],["خَوْفٌ","fear"],["عَلَيْهِمْ","on them"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"464":["(Mereka bersenang hati dengan nikmat) atau pahala (dari Allah dan karunia) atau tambahan atasnya (dan bahwa) dibaca anna sebagai ma'thuf kepada 'ni'mah' atau 'inna' sebagai isti'naf atau permulaan kalimat (Allah tidak menyia-nyiakan pahala orang-orang yang beriman) tetapi sebaliknya akan memberi mereka ganjaran.",[["۞ يَسْتَبْشِرُونَ","They receive good tidings"],["بِنِعْمَةٍۢ","of Favor"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["وَفَضْلٍۢ","and Bounty"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يُضِيعُ","let go waste"],["أَجْرَ","(the) reward"],["ٱلْمُؤْمِنِينَ","(of) the believers"]]],"465":["(Orang-orang) menjadi subjek atau mubtada (yang memenuhi panggilan Allah dan rasul-Nya) agar keluar untuk berperang, yakni sewaktu Abu Sufyan dan kawan-kawannya hendak mengulangi peperangan dan berjanji dengan Nabi saw. serta para sahabat akan bertemu kembali di pasar Badar setahun setelah perang Uhud (setelah mereka mendapat luka) yakni di Uhud, sedangkan yang menjadi predikat atau khabar mubtadanya ialah: (bagi orang-orang yang berbuat kebaikan di antara mereka) dengan menaati-Nya (dan menjaga diri) dari menyalahi-Nya (tersedia pahala besar) yaitu surga.",[["ٱلَّذِينَ","Those who"],["ٱسْتَجَابُوا۟","responded"],["لِلَّهِ","to Allah"],["وَٱلرَّسُولِ","and the Messenger"],["مِنۢ","from"],["بَعْدِ","after"],["مَآ","what"],["أَصَابَهُمُ","befell them "],["ٱلْقَرْحُ ۚ","the injury "],["لِلَّذِينَ","for those who"],["أَحْسَنُوا۟","did good"],["مِنْهُمْ","among them"],["وَٱتَّقَوْا۟","and feared Allah"],["أَجْرٌ","(is) a reward "],["عَظِيمٌ","great"]]],"466":["(Yakni orang-orang) badal atau sifat dari 'alladziina' yang sebelumnya (kepada mereka ada yang mengatakan) yakni Na'im bin Masud Al-Asyjai (\"Sesungguhnya manusia) yaitu Abu Sofyan dan kawan-kawannya (telah menghimpun pasukan untuk menyerang kamu) atau untuk membasmimu (maka takutlah kepada mereka\") dan jangan hadapi mereka. (Maka ucapan itu menambah keimanan mereka) bertambah kepercayaan dan keyakinan mereka terhadap Allah swt. (dan jawaban mereka, \"Cukuplah bagi kami Allah) sebagai pembela terhadap mereka (dan Dialah sebaik-baik pelindung\") tempat menyerahkan segala urusan. Nabi saw. bersama kaum Muslimin pergi ke pasar Badar tetapi tidak menemui Abu Sofyan dan kawan-kawannya, Allah telah meniupkan rasa cemas dan ketakutan ke dalam hati mereka sehingga mereka tidak muncul. Sebaliknya di kalangan kaum Muslimin dan penduduk berlangsung jual beli sehingga mereka beroleh laba dan keuntungan. Firman Allah swt. selanjutnya.",[["ٱلَّذِينَ","Those who"],["قَالَ","said"],["لَهُمُ","to them"],["ٱلنَّاسُ","[the people]"],["إِنَّ","Indeed"],["ٱلنَّاسَ","the people"],["قَدْ","(have) certainly"],["جَمَعُوا۟","gathered"],["لَكُمْ","against you"],["فَٱخْشَوْهُمْ","so fear them"],["فَزَادَهُمْ","But it increased them"],["إِيمَـٰنًۭا","(in) faith"],["وَقَالُوا۟","and they said"],["حَسْبُنَا","Sufficient for us"],["ٱللَّهُ","(is) Allah"],["وَنِعْمَ","and (He is the) best"],["ٱلْوَكِيلُ","[the] Disposer of affairs"]]],"467":["(Maka kembalilah mereka) dari Badar (dengan nikmat dan karunia dari Allah) yakni keselamatan dan keuntungan (tanpa mendapat bencana) baik luka atau kematian (dan mereka mengikuti keridaan Allah) yakni dengan menaati-Nya dan rasul-Nya supaya keluar berperang. (Dan Allah mempunyai karunia yang besar) terhadap ahli taat dan ibadah.",[["فَٱنقَلَبُوا۟","So they returned"],["بِنِعْمَةٍۢ","with (the) Favor"],["مِّنَ","of"],["ٱللَّهِ","Allah"],["وَفَضْلٍۢ","and Bounty"],["لَّمْ","not"],["يَمْسَسْهُمْ","touched them"],["سُوٓءٌۭ","any harm"],["وَٱتَّبَعُوا۟","And they followed"],["رِضْوَٰنَ","(the) pleasure"],["ٱللَّهِ ۗ","(of) Allah"],["وَٱللَّهُ","and Allah"],["ذُو","(is) Possessor"],["فَضْلٍ","(of) Bounty"],["عَظِيمٍ","great"]]],"468":["(Sesungguhnya mereka itu) yakni yang mengatakan bahwa manusia telah menghimpun pasukan dan seterusnya tadi (hanyalah setan yang menakut-nakuti) kamu dengan (kawan-kawannya) yakni orang-orang kafir (maka janganlah kamu takut kepada mereka hanya takutlah kepada-Ku) jika meninggalkan perintah-Ku (sekiranya kamu benar-benar beriman.)",[["إِنَّمَا","(It is) only"],["ذَٰلِكُمُ","that"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["يُخَوِّفُ","frightens (you)"],["أَوْلِيَآءَهُۥ","(of) his allies"],["فَلَا","So (do) not"],["تَخَافُوهُمْ","fear them"],["وَخَافُونِ","but fear Me"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"469":["(Janganlah kamu menjadi sedih oleh) ada yang membaca 'yuhzinka' dan ada pula 'yahzunka', berasal dari kata 'ahzanahu' (orang-orang yang cepat jatuh dalam kekafiran) yakni orang-orang yang membela kekafiran itu seperti warga Mekah dan orang-orang munafik, maksudnya jangan kamu pedulikan hal itu. (Sesungguhnya mereka tak sekali-kali dapat memberi mudarat kepada Allah sedikit pun) dengan perbuatan mereka itu, dan mereka hanya membawa kerusakan bagi diri mereka sendiri (Allah menghendaki agar tidak memberi mereka sesuatu di akhirat) maksudnya surga, oleh sebab itu mereka dibiarkan-Nya (dan bagi mereka siksa yang besar) dalam neraka.",[["وَلَا","And (let) not"],["يَحْزُنكَ","grieve you"],["ٱلَّذِينَ","those who"],["يُسَـٰرِعُونَ","hasten"],["فِى","in(to)"],["ٱلْكُفْرِ ۚ","[the] disbelief"],["إِنَّهُمْ","Indeed, they"],["لَن","never"],["يَضُرُّوا۟","will harm"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا ۗ","(in) anything"],["يُرِيدُ","intends"],["ٱللَّهُ","Allah"],["أَلَّا","that not"],["يَجْعَلَ","He will set"],["لَهُمْ","for them"],["حَظًّۭا","any portion"],["فِى","in"],["ٱلْـَٔاخِرَةِ ۖ","the Hereafter"],["وَلَهُمْ","And for them"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌ","great"]]],"470":["(Sesungguhnya orang-orang yang menukar keimanan dengan kekafiran) artinya mengambil kekafiran sebagai ganti dari keimanan (tidaklah memberi mudarat kepada Allah) dengan kekafiran mereka itu (sedikit pun dan bagi mereka siksa yang pedih) atau menyakitkan.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ٱشْتَرَوُا۟","(have) purchased"],["ٱلْكُفْرَ","[the] disbelief"],["بِٱلْإِيمَـٰنِ","with the faith"],["لَن","never"],["يَضُرُّوا۟","will they harm"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا","(in) anything"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"]]],"471":["(Janganlah sekali-kali menyangka) ada yang memakai 'ya' dan ada pula 'ta' (orang-orang kafir itu bahwa Kami menangguhkan) artinya penangguhan Kami (bagi mereka) yakni dengan memanjangkan umur dan menangguhkan hukuman (lebih baik bagi diri mereka). 'Anna' bersama kedua ma'mulnya menurut qiraat 'yahsabanna' menempati kedudukan dua maf'ulnya, 'tahsabanna' berkedudukan sebagai maf'ul kedua dari 'tahsabanna' (\"Sesungguhnya Kami menangguhkan mereka itu hanyalah supaya dosa mereka bertambah-tambah) disebabkan banyaknya maksiat (dan bagi mereka siksa yang menghinakan\") di akhirat.",[["وَلَا","And (let) not"],["يَحْسَبَنَّ","think"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieved"],["أَنَّمَا","that"],["نُمْلِى","We give respite"],["لَهُمْ","to them"],["خَيْرٌۭ","(is) good"],["لِّأَنفُسِهِمْ ۚ","for themselves"],["إِنَّمَا","Only"],["نُمْلِى","We give respite"],["لَهُمْ","to them"],["لِيَزْدَادُوٓا۟","so that they may increase"],["إِثْمًۭا ۚ","(in) sins"],["وَلَهُمْ","and for them"],["عَذَابٌۭ","(is) a punishment"],["مُّهِينٌۭ","humiliating"]]],"472":["(Allah sekali-kali tidak akan meninggalkan) membiarkan (orang-orang yang beriman dalam keadaan yang kamu) hai manusia (berada di atasnya) artinya yang kamu alami berupa campur aduknya yang ikhlas dengan yang lainnya (sampai Dia memisahkan) dibaca yamiiza atau yumayyiza artinya menyisihkan (orang-orang yang jelek) yaitu orang munafik (dari yang baik) yaitu orang beriman. Caranya ialah dengan tugas-tugas berat sehingga menyingkapkan yang demikian itu, misalnya seperti yang dilakukan-Nya di waktu perang Uhud. (Dan Allah sekali-kali tidak akan memperlihatkan padamu hal-hal gaib) sehingga kamu dapat mengenal mana yang munafik dan mana yang baik sebelum dipisahkan Allah itu (tetapi Allah memilih di antara rasul-rasul-Nya siapa yang dikehendaki-Nya) untuk diberitahukan-Nya hal-hal gaib itu seperti kepada Nabi saw. yang disingkapkan-Nya perihal orang-orang munafik. (Oleh sebab itu berimanlah kamu kepada Allah dan rasul-rasul-Nya dan jika kamu beriman dan bertakwa) artinya menjaga dirimu dari kemunafikan (maka akan beroleh pahala yang besar.)",[["مَّا","Not"],["كَانَ","is"],["ٱللَّهُ","Allah"],["لِيَذَرَ","to leave"],["ٱلْمُؤْمِنِينَ","the believers"],["عَلَىٰ","on"],["مَآ","what"],["أَنتُمْ","you (are)"],["عَلَيْهِ","in [it]"],["حَتَّىٰ","until"],["يَمِيزَ","He separates"],["ٱلْخَبِيثَ","the evil"],["مِنَ","from"],["ٱلطَّيِّبِ ۗ","the good"],["وَمَا","And not"],["كَانَ","is"],["ٱللَّهُ","Allah"],["لِيُطْلِعَكُمْ","to inform you"],["عَلَى","about"],["ٱلْغَيْبِ","the unseen"],["وَلَـٰكِنَّ","[and] but"],["ٱللَّهَ","Allah"],["يَجْتَبِى","chooses"],["مِن","from"],["رُّسُلِهِۦ","His Messengers"],["مَن","whom"],["يَشَآءُ ۖ","He wills"],["فَـَٔامِنُوا۟","so believe"],["بِٱللَّهِ","in Allah"],["وَرُسُلِهِۦ ۚ","and His Messengers"],["وَإِن","and if"],["تُؤْمِنُوا۟","you believe"],["وَتَتَّقُوا۟","and fear (Allah)"],["فَلَكُمْ","then for you"],["أَجْرٌ","(is a) reward"],["عَظِيمٌۭ","great"]]],"473":["(Sekali-kali janganlah menyangka) dengan memakai 'ya' atau 'ta' (orang-orang yang bakhil dengan harta yang diberikan Allah dan karunia-Nya) artinya mengeluarkan zakatnya (bahwa itu) maksudnya kebakhilan itu (baik bagi mereka) menjadi maf'ul yang kedua sedangkan dhamir sebagai pemisah. Maf'ul yang pertama ialah 'kebakhilan mereka' yang diperkirakan sebelum isim maushul jika dibaca dengan 'ta' dan sebelum dhamir jika dengan 'ya' (tetapi itu buruk bagi mereka. Mereka akan dikalungi harta yang mereka bakhilkan) tidak dikeluarkan zakatnya (pada hari kiamat) yakni dengan melilitkan ular pada lehernya dan ular itu mematuknya sebagaimana tercantum dalam sebuah hadis. (Milik Allahlah segala warisan langit dan bumi) yang akan diwarisi-Nya setelah lenyap atau musnahnya penghuni langit dan bumi. (Dan Allah Maha Mengetahui apa yang kamu kerjakan) sehingga akan mendapat balasan daripada-Nya. Ada yang membaca 'ta'maluuna' dengan 'ta' ada pula 'ya'maluuna' dengan 'ya.'",[["وَلَا","And (let) not"],["يَحْسَبَنَّ","think"],["ٱلَّذِينَ","those who"],["يَبْخَلُونَ","withhold"],["بِمَآ","of what"],["ءَاتَىٰهُمُ","(has) given them"],["ٱللَّهُ","Allah"],["مِن","of"],["فَضْلِهِۦ","His Bounty"],["هُوَ","(that) it"],["خَيْرًۭا","(is) good"],["لَّهُم ۖ","for them"],["بَلْ","Nay"],["هُوَ","it"],["شَرٌّۭ","(is) bad"],["لَّهُمْ ۖ","for them"],["سَيُطَوَّقُونَ","Their necks will be encircled"],["مَا","(with) what"],["بَخِلُوا۟","they withheld"],["بِهِۦ","[with it]"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) [the] Resurrection"],["وَلِلَّهِ","And for Allah"],["مِيرَٰثُ","(is the) heritage"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۗ","and the earth"],["وَٱللَّهُ","And Allah"],["بِمَا","with what"],["تَعْمَلُونَ","you do"],["خَبِيرٌۭ","(is) All-Aware"]]],"474":["(Sungguh Allah telah mendengar ucapan orang-orang yang mengatakan, \"Sesungguhnya Allah itu miskin dan kami kaya.\") Mereka itu ialah orang-orang Yahudi yang mengatakannya tatkala turun ayat \"Siapakah yang bersedia memberi pinjaman kepada Allah suatu pinjaman yang baik?\" Kata mereka, \"Sekiranya Dia kaya tentulah Dia tidak akan meminjam kepada kita!\" (Kami akan mencatat) maksudnya akan menyuruh mencatat (apa yang mereka katakan itu) yakni dalam buku catatan amal perbuatan mereka agar mereka menerima balasannya. Menurut suatu qiraat dibaca 'sayuktabu' bukan 'sanaktubu.' (Dan) Kami catat pula (pembunuhan mereka) memakai baris di atas atau baris di depan (atas nabi-nabi tanpa alasan yang benar dan Kami katakan) ada yang membaca 'naquulu' dan ada pula 'yaquulu' yang berarti bahwa yang mengatakan itu ialah Allah yakni di akhirat kelak, perantaraan lisan para malaikat ('Rasailah olehmu azab neraka) lalu dikatakan pula kepada mereka bila mereka dilemparkan ke dalam neraka.",[["لَّقَدْ","Certainly"],["سَمِعَ","heard"],["ٱللَّهُ","Allah"],["قَوْلَ","(the) saying"],["ٱلَّذِينَ","(of) those who"],["قَالُوٓا۟","said"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["فَقِيرٌۭ","(is) poor"],["وَنَحْنُ","while we"],["أَغْنِيَآءُ ۘ","(are) rich"],["سَنَكْتُبُ","We will record"],["مَا","what"],["قَالُوا۟","they said"],["وَقَتْلَهُمُ","and their killing"],["ٱلْأَنۢبِيَآءَ","the Prophets"],["بِغَيْرِ","without"],["حَقٍّۢ","(any) right"],["وَنَقُولُ","and We will say"],["ذُوقُوا۟","Taste"],["عَذَابَ","(the) punishment"],["ٱلْحَرِيقِ","(of) the Burning Fire"]]],"475":["(Demikian itu) maksudnya azab neraka tadi (disebabkan perbuatan tanganmu sendiri) diibaratkan dengan tangan karena kebanyakan perbuatan manusia dilaksanakan dengannya (dan bahwa Allah sekali-kali tidak menganiaya) artinya tidak berbuat aniaya atau melakukan keaniayaan (terhadap hamba-hamba-Nya) Allah tidak akan menyiksa orang-orang yang tidak bersalah atau berdosa.",[["ذَٰلِكَ","That"],["بِمَا","(is) because"],["قَدَّمَتْ","(of what) sent forth"],["أَيْدِيكُمْ","your hands"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["لَيْسَ","is not"],["بِظَلَّامٍۢ","unjust"],["لِّلْعَبِيدِ","to (His) slaves"]]],"476":["(Yakni orang-orang yang) 'na'at' atau sifat bagi alladziina yang sebelumnya (mengatakan) kepada Muhammad (\"Sesungguhnya Allah telah menitahkan kepada kami) dalam Taurat (supaya kami tidak beriman kepada seorang rasul) artinya tidak membenarkannya (sebelum ia mendatangkan kepada kami suatu kurban yang dimakan api\"). Maka kami tidak akan beriman kepadamu sebelum membawakan kurban, pemberian, yang mendekatkan diri kepada Allah berupa ternak atau lainnya. Jika kurban itu diterima, maka dari langit akan muncul api putih yang akan membakarnya. Dan jika tidak, maka ia akan tetap tinggal di tempatnya tanpa ada yang menyentuhnya. Hal ini diperintahkan kepada Bani Israel tetapi kepada Almasih dan Muhammad tidak demikian halnya, Allah swt. berfirman (Katakanlah) kepada mereka sebagai celaan (\"Bukankah telah datang kepadamu beberapa orang rasul sebelumku dengan membawa keterangan-keterangan nyata) atau mukjizat (dan dengan apa yang kamu sebutkan itu) seperti Zakaria dan Yahya, tetapi mereka kamu bunuh juga. Perkataan ini ditujukan kepada orang-orang Yahudi yang hidup di masa Nabi kita saw. walaupun perbuatan itu dari nenek moyang mereka karena mereka menyetujuinya. (Maka kenapa kamu bunuh mereka jika kamu orang-orang yang benar?\") maksudnya jika kamu benar-benar beriman ketika melakukan pelanggaran itu.",[["ٱلَّذِينَ","Those who"],["قَالُوٓا۟","said"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَهِدَ","(has) taken promise"],["إِلَيْنَآ","from us"],["أَلَّا","that not"],["نُؤْمِنَ","we (should) believe"],["لِرَسُولٍ","in a Messenger"],["حَتَّىٰ","until"],["يَأْتِيَنَا","he brings to us"],["بِقُرْبَانٍۢ","a sacrifice "],["تَأْكُلُهُ","consumes it"],["ٱلنَّارُ ۗ","the fire"],["قُلْ","Say"],["قَدْ","Surely"],["جَآءَكُمْ","came to you"],["رُسُلٌۭ","Messengers"],["مِّن","from"],["قَبْلِى","before me"],["بِٱلْبَيِّنَـٰتِ","with the clear Signs"],["وَبِٱلَّذِى","and with what"],["قُلْتُمْ","you speak"],["فَلِمَ","So why"],["قَتَلْتُمُوهُمْ","you killed them"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"477":["(Jika mereka mendustakanmu, maka sesungguhnya rasul-rasul yang sebelum kamu pun telah didustakan pula, padahal mereka membawa keterangan-keterangan yang nyata) yakni mukjizat (dan zubur) maksudnya shuhuf-shuhuf seperti shuhuf Nabi Ibrahim (dan Alkitab) menurut satu qiraat dengan memakai 'ba' pada al-kitab dan az-zubur (yang terang) yakni Taurat dan Injil, maka bersabarlah kamu sebagaimana mereka telah bersabar.",[["فَإِن","Then if"],["كَذَّبُوكَ","they reject you"],["فَقَدْ","then certainly"],["كُذِّبَ","were rejected"],["رُسُلٌۭ","Messengers"],["مِّن","from"],["قَبْلِكَ","before you"],["جَآءُو","(who) came"],["بِٱلْبَيِّنَـٰتِ","with the clear Signs"],["وَٱلزُّبُرِ","and the Scriptures"],["وَٱلْكِتَـٰبِ","and the Book "],["ٱلْمُنِيرِ","[the] Enlightening"]]],"478":["(Setiap diri akan merasai kematian dan hanya pada hari kiamatlah pahalamu disempurnakan) artinya pada hari kiamatlah ganjaran amal perbuatanmu dipenuhi dengan cukup. (Barang siapa yang dijauhkan) setelah itu (dari neraka dan dimasukkan ke dalam surga, maka sungguh ia beruntung) karena mencapai apa yang dicita-citakannya. (Kehidupan dunia ini tidak lain) maksudnya hidup di dunia ini (hanyalah kesenangan yang memperdayakan semata) artinya yang tidak sebenarnya karena dinikmati hanya sementara lalu ia segera sirna.",[["كُلُّ","Every"],["نَفْسٍۢ","soul"],["ذَآئِقَةُ","(will) taste"],["ٱلْمَوْتِ ۗ","[the] death"],["وَإِنَّمَا","and only"],["تُوَفَّوْنَ","you will be paid in full"],["أُجُورَكُمْ","your reward"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۖ","(of) [the] Resurrection"],["فَمَن","Then whoever"],["زُحْزِحَ","is drawn away"],["عَنِ","from"],["ٱلنَّارِ","the Fire"],["وَأُدْخِلَ","and admitted"],["ٱلْجَنَّةَ","(to) Paradise"],["فَقَدْ","then surely"],["فَازَ ۗ","he is successful"],["وَمَا","And not"],["ٱلْحَيَوٰةُ","(is) the life"],["ٱلدُّنْيَآ","(of) the world"],["إِلَّا","except"],["مَتَـٰعُ","enjoyment"],["ٱلْغُرُورِ","(of) delusion"]]],"479":["(Kamu sungguh-sungguh akan diuji) karena berturut-turutnya beberapa 'nun' maka nun tanda rafa'nya dihilangkan, begitu juga 'wau' dhamir jamak karena bertemunya dua wawu sakin, sedangkan artinya ialah kamu sungguh-sungguh akan diuji atau dicoba (mengenai hartamu) dengan beban-beban dan kewajiban yang harus kamu penuhi (dan dirimu) dengan ibadat dan ujian berupa malapetaka (dan sungguh akan kamu dengar dari orang-orang yang diberi Kitab sebelum kamu) yakni dari orang-orang Yahudi dan Nasrani (dan dari orang-orang musyrik) dari kalangan Arab (gangguan menyakitkan yang banyak sekali) berupa makian dan tuduhan serta godaan dan gangguan terhadap wanita-wanitamu. (Jika kamu bersabar) atas tantangan itu (dan bertakwa) kepada Allah (maka demikian itu termasuk di antara pekerjaan-pekerjaan utama) termasuk hal-hal yang harus dipentingkan dan wajib dihadapi dengan keteguhan hati dan kesabaran yang penuh.",[["۞ لَتُبْلَوُنَّ","You will certainly be tested"],["فِىٓ","in"],["أَمْوَٰلِكُمْ","your wealth"],["وَأَنفُسِكُمْ","and yourselves"],["وَلَتَسْمَعُنَّ","And you will certainly hear"],["مِنَ","from"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["مِن","from"],["قَبْلِكُمْ","before you"],["وَمِنَ","and from"],["ٱلَّذِينَ","those who"],["أَشْرَكُوٓا۟","associate partners with Allah "],["أَذًۭى","hurtful things"],["كَثِيرًۭا ۚ","many"],["وَإِن","and if"],["تَصْبِرُوا۟","you are patient"],["وَتَتَّقُوا۟","and fear (Allah)"],["فَإِنَّ","then indeed"],["ذَٰلِكَ","that"],["مِنْ","(is) of"],["عَزْمِ","the matters"],["ٱلْأُمُورِ","(of) determination"]]],"480":["(Dan) ingatlah (ketika Allah mengambil ikrar dari orang-orang yang diberi Alkitab) yakni tugas yang diberikan kepada mereka dalam Taurat (\"Hendaklah kamu menerangkannya) maksudnya isi Alkitab itu (kepada manusia dan janganlah kamu menyembunyikannya\") yakni Alkitab itu. Kedua kata kerja pada kalimat ini dengan memakai 'ta' dan 'ya.' (Lalu mereka melemparkannya) maksudnya ikrar tersebut (ke belakang punggung mereka) artinya tidak mereka penuhi dan amalkan (dan mereka menukarnya dengan) mereka ambil sebagai gantinya (harga yang sedikit) berupa harta benda dunia yang mereka pungut dari rakyat bawahan dengan keunggulan mereka dalam ilmu Alkitab. Maka ilmu itu mereka sembunyikan karena takut akan lepas dari tangan. (Maka amat jeleklah tukaran yang mereka terima) atau penukaran yang mereka lakukan itu.",[["وَإِذْ","And when"],["أَخَذَ","took"],["ٱللَّهُ","Allah"],["مِيثَـٰقَ","a Covenant"],["ٱلَّذِينَ","(from) those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["لَتُبَيِّنُنَّهُۥ","You certainly make it clear"],["لِلنَّاسِ","to the mankind"],["وَلَا","and (do) not"],["تَكْتُمُونَهُۥ","conceal it"],["فَنَبَذُوهُ","Then they threw it"],["وَرَآءَ","behind"],["ظُهُورِهِمْ","their backs"],["وَٱشْتَرَوْا۟","and they exchanged"],["بِهِۦ","[with] it"],["ثَمَنًۭا","(for) a price"],["قَلِيلًۭا ۖ","little"],["فَبِئْسَ","And wretched"],["مَا","(is) what"],["يَشْتَرُونَ","they purchase"]]],"481":["(Janganlah sekali-kali kamu kira) dengan memakai 'ta' dan 'ya' (bahwa orang-orang yang merasa gembira dengan apa yang telah mereka lakukan) yakni dengan apa yang telah mereka perbuat yaitu menyesatkan manusia (dan mereka ingin supaya dipuji terhadap perbuatan yang belum mereka kerjakan) yakni berpegang kepada kebenaran padahal mereka dalam kesesatan (janganlah kamu menyangka mereka) merupakan taukid atau pengukuhan dengan kedua versinya, memakai 'ta' dan 'ya' (terlepas) artinya berada di suatu tempat yang bebas (dari siksa) di akhirat tetapi mereka berada di suatu tempat di mana mereka akan menerima siksa yaitu di neraka Jahanam (dan bagi mereka siksa yang pedih) menyakitkan. Kedua maf'ul yahsabu yang pertama terkandung di dalam kedua maf'ul yahsabu yang kedua berdasarkan qiraat yahsabu sedangkan menurut qiraat tahsabu hanya maf'ul kedualah yang dibuang.",[["لَا","(Do) not"],["تَحْسَبَنَّ","think"],["ٱلَّذِينَ","(that) those who"],["يَفْرَحُونَ","rejoice"],["بِمَآ","in what"],["أَتَوا۟","(they have) brought"],["وَّيُحِبُّونَ","and they love"],["أَن","that"],["يُحْمَدُوا۟","they be praised"],["بِمَا","for what"],["لَمْ","not"],["يَفْعَلُوا۟","they do "],["فَلَا","so (do) not"],["تَحْسَبَنَّهُم","think (that) they"],["بِمَفَازَةٍۢ","(will) escape"],["مِّنَ","from"],["ٱلْعَذَابِ ۖ","the punishment"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is a) punishment"],["أَلِيمٌۭ","painful"]]],"482":["(Milik Allahlah kerajaan langit dan bumi) maksudnya perbendaharaan hujan, rezeki, tumbuh-tumbuhan dan lain-lain (dan Allah Maha Kuasa atas segala sesuatu) di antaranya menyiksa orang-orang kafir dan membebaskan orang-orang beriman.",[["وَلِلَّهِ","And for Allah"],["مُلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۗ","and the earth"],["وَٱللَّهُ","and Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌ","All-Powerful"]]],"483":["(Sesungguhnya pada penciptaan langit dan bumi) dan keajaiban-keajaiban yang terdapat pada keduanya (serta pergantian malam dan siang) dengan datang dan pergi serta bertambah dan berkurang (menjadi tanda-tanda) atau bukti-bukti atas kekuasaan Allah swt. (bagi orang-orang yang berakal) artinya yang mempergunakan pikiran mereka.",[["إِنَّ","Indeed"],["فِى","in"],["خَلْقِ","(the) creation"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَٱخْتِلَـٰفِ","and (in the) alternation"],["ٱلَّيْلِ","(of) the night"],["وَٱلنَّهَارِ","and the day"],["لَـَٔايَـٰتٍۢ","(are) surely Signs"],["لِّأُو۟لِى","for men"],["ٱلْأَلْبَـٰبِ","(of) understanding"]]],"484":["(Yakni orang-orang yang) menjadi 'na`at' atau badal bagi yang sebelumnya (mengingat Allah di waktu berdiri dan duduk dan ketika berbaring) artinya dalam keadaan bagaimana pun juga sedang menurut Ibnu Abbas mengerjakan salat dalam keadaan tersebut sesuai dengan kemampuan (dan mereka memikirkan tentang kejadian langit dan bumi) untuk menyimpulkan dalil melalui keduanya akan kekuasaan Allah, kata mereka: (\"Wahai Tuhan kami! Tidaklah Engkau ciptakan ini) maksudnya makhluk yang kami saksikan ini (dengan sia-sia) menjadi hal sebaliknya semua ini menjadi bukti atas kesempurnaan kekuasaan-Mu (Maha Suci Engkau) artinya tidak mungkin Engkau akan berbuat sia-sia (maka lindungilah kami dari siksa neraka.)",[["ٱلَّذِينَ","Those who"],["يَذْكُرُونَ","remember"],["ٱللَّهَ","Allah"],["قِيَـٰمًۭا","standing"],["وَقُعُودًۭا","and sitting"],["وَعَلَىٰ","and on"],["جُنُوبِهِمْ","their sides"],["وَيَتَفَكَّرُونَ","and they reflect"],["فِى","on"],["خَلْقِ","(the) creation"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["رَبَّنَا","Our Lord"],["مَا","not"],["خَلَقْتَ","You have created"],["هَـٰذَا","this"],["بَـٰطِلًۭا","(in) vain"],["سُبْحَـٰنَكَ","Glory be to You"],["فَقِنَا","so save us"],["عَذَابَ","(from the) punishment"],["ٱلنَّارِ","(of) the Fire"]]],"485":["(Wahai Tuhan kami! Sesungguhnya barang siapa yang Engkau masukkan ke dalam neraka) untuk hidup kekal di sana (maka berarti Engkau telah menghinakannya dan tiadalah bagi orang-orang yang aniaya) maksudnya orang-orang yang kafir; di sini ditempatkan zhahir pada tempat mudhmar untuk mengingatkan dikhususkannya kehinaan itu bagi mereka (dari) merupakan tambahan (seorang penolong pun) yang akan melindungi mereka dari siksa Allah swt.",[["رَبَّنَآ","Our Lord"],["إِنَّكَ","indeed [You]"],["مَن","whom"],["تُدْخِلِ","You admit"],["ٱلنَّارَ","(to) the Fire"],["فَقَدْ","then surely"],["أَخْزَيْتَهُۥ ۖ","You (have) disgraced him"],["وَمَا","and not"],["لِلظَّـٰلِمِينَ","for the wrongdoers"],["مِنْ","(are) any"],["أَنصَارٍۢ","helpers"]]],"486":["(Wahai Tuhan kami! Sesungguhnya kami telah mendengar seorang penyeru yang menyeru) manusia (untuk beriman) kepadanya, yaitu Muhammad atau Alquran (supaya) maksudnya yakni: ('Berimanlah kepada Tuhanmu!' Maka kami pun berimanlah) kepada-Nya (Wahai Tuhan kami! Ampunilah bagi kami dosa-dosa kami dan hapuskanlah) tutup (dari kami kesalahan-kesalahan kami) artinya janganlah dibukakan kepada umum dengan memberikan hukuman terhadapnya (dan wafatkanlah kami) cabutlah nyawa kami (bersama) golongan (orang-orang yang berbakti) yakni para nabi dan orang-orang saleh.",[["رَّبَّنَآ","Our Lord"],["إِنَّنَا","indeed we"],["سَمِعْنَا","[we] heard"],["مُنَادِيًۭا","a caller"],["يُنَادِى","calling"],["لِلْإِيمَـٰنِ","to the faith"],["أَنْ","that"],["ءَامِنُوا۟","Believe"],["بِرَبِّكُمْ","in your Lord"],["فَـَٔامَنَّا ۚ","so we have believed"],["رَبَّنَا","Our Lord"],["فَٱغْفِرْ","so forgive"],["لَنَا","for us"],["ذُنُوبَنَا","our sins"],["وَكَفِّرْ","and remove"],["عَنَّا","from us"],["سَيِّـَٔاتِنَا","our evil deeds"],["وَتَوَفَّنَا","and cause us to die"],["مَعَ","with"],["ٱلْأَبْرَارِ","the righteous"]]],"487":["(Wahai Tuhan kami! Berilah kami apa yang telah Engkau janjikan kepada kami) (atas) artinya dengan perantaraan (para rasul-Mu) berupa nikmat dan karunia serta apa-apa yang mereka mohonkan walaupun janji Allah itu tidak bertentangan dengan permohonan orang yang meminta agar ia termasuk dalam golongan orang-orang yang diberi karunia disebabkan ia belum beroleh kepastian bahwa permohonannya itu akan dikabulkan. Mengenai disebutnya 'Wahai Tuhan kami' secara berulang-ulang maka itu menyatakan ketundukan dan kerendahan hati yang sedalam-dalamnya. (Dan janganlah Engkau hinakan kami pada hari kiamat, sesungguhnya Engkau tidak menyalahi janji.\") yaitu janji dengan kebangkitan dan pembalasan.",[["رَبَّنَا","Our Lord"],["وَءَاتِنَا","grant us"],["مَا","what"],["وَعَدتَّنَا","You promised us"],["عَلَىٰ","through"],["رُسُلِكَ","Your Messengers"],["وَلَا","and (do) not"],["تُخْزِنَا","disgrace us"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) [the] Resurrection"],["إِنَّكَ","Indeed, You"],["لَا","(do) not"],["تُخْلِفُ","break"],["ٱلْمِيعَادَ","the promise"]]],"488":["(Maka Tuhan mereka memperkenankan bagi mereka) permohonan mereka (bahwa Aku tidak akan menyia-nyiakan amalan orang-orang yang beramal di antara kamu baik laki-laki maupun perempuan, sebagian kamu) adalah (dari sebagian yang lain) artinya laki-laki adalah turunan wanita sebaliknya wanita adalah keturunan laki-laki. Kalimat ini memperkuat kalimat yang sebelumnya yakni bahwa mereka akan sama-sama menerima balasan dari amal perbuatan masing-masing dan bahwa mereka sama-sama tidak akan disepelekan. Lanjutan ayat berikut turun ketika Ummu Salamah mengatakan kepada Rasulullah, \"Wahai Rasulullah! Tidak pernah saya dengar wanita disebut-sebut dalam soal hijrah.\" (Maka orang-orang yang berhijrah) dari Mekah ke Madinah (yang diusir dari kampung halamannya serta disakiti pada jalan-Ku) maksudnya karena agama-Ku (dan yang berperang) melawan orang-orang kafir (dan orang-orang yang gugur) di jalan-Ku baik memakai tasydid atau tidak dan menurut satu qiraat dengan mendahulukannya (niscaya Aku hapuskan kesalahan-kesalahan mereka) Aku tutupi dosa-dosa mereka dengan ampunan-Ku (dan Kumasukkan mereka ke dalam surga yang mengalir di bawahnya sungai-sungai sebagai pahala) mashdar dari pengertian 'Kuhapus' dan memperkokoh maknanya (dari sisi Allah) terdapat perpalingan kedudukan-Nya sebagai pembicara (dan Allah di sisi-Nya terdapat pahala yang baik.) sebagai balasan. Ayat berikut turun pula tatkala kaum Muslimin mengatakan bahwa musuh Allah kelihatan berbahagia sedangkan mereka dalam keadaan susah dan menderita:",[["فَٱسْتَجَابَ","Then responded"],["لَهُمْ","to them"],["رَبُّهُمْ","their Lord"],["أَنِّى","Indeed, I"],["لَآ","(will) not"],["أُضِيعُ","(let go) waste"],["عَمَلَ","deeds"],["عَـٰمِلٍۢ","(of the) doer"],["مِّنكُم","among you"],["مِّن","[from]"],["ذَكَرٍ","(whether) male"],["أَوْ","or"],["أُنثَىٰ ۖ","female"],["بَعْضُكُم","each of you"],["مِّنۢ","from"],["بَعْضٍۢ ۖ","(the) other"],["فَٱلَّذِينَ","So those who"],["هَاجَرُوا۟","emigrated"],["وَأُخْرِجُوا۟","and were driven out"],["مِن","from"],["دِيَـٰرِهِمْ","their homes"],["وَأُوذُوا۟","and were harmed"],["فِى","in"],["سَبِيلِى","My way"],["وَقَـٰتَلُوا۟","and fought"],["وَقُتِلُوا۟","and were killed "],["لَأُكَفِّرَنَّ","surely I (will) remove"],["عَنْهُمْ","from them"],["سَيِّـَٔاتِهِمْ","their evil deeds"],["وَلَأُدْخِلَنَّهُمْ","and surely I will admit them"],["جَنَّـٰتٍۢ","(to) Gardens"],["تَجْرِى","flowing"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers "],["ثَوَابًۭا","a reward"],["مِّنْ","from"],["عِندِ","[near]"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","And Allah "],["عِندَهُۥ","with Him"],["حُسْنُ","(is the) best"],["ٱلثَّوَابِ","reward"]]],"489":["(Janganlah sekali-kali kamu terpedaya oleh keleluasaan orang-orang kafir bepergian) artinya bergerak ke mana mereka sukai (di dalam negeri) untuk berniaga dan berusaha.",[["لَا","(Let) not"],["يَغُرَّنَّكَ","deceive you"],["تَقَلُّبُ","(the) movement"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["فِى","in"],["ٱلْبِلَـٰدِ","the land"]]],"490":["(Itu hanyalah kesenangan sementara) yang mereka nikmati di dunia dalam waktu singkat kemudian akan lenyap (kemudian tempat tinggal mereka ialah neraka Jahanam dan itulah tempat yang seburuk-buruknya.)",[["مَتَـٰعٌۭ","An enjoyment"],["قَلِيلٌۭ","little"],["ثُمَّ","then"],["مَأْوَىٰهُمْ","their abode"],["جَهَنَّمُ ۚ","(is) hell "],["وَبِئْسَ","[and] a wretched"],["ٱلْمِهَادُ","[the] resting place"]]],"491":["(Akan tetapi orang-orang yang bertakwa kepada Tuhannya bagi mereka surga-surga yang di bawahnya mengalir sungai, mereka kekal) maksudnya ditakdirkan kekal (padanya sebagai tempat tinggal) yang biasanya disediakan buat tamu-tamu; dijadikan manshub karena kedudukannya sebagai hal dari jannaat sedangkan sebagai amilnya ialah pengertian zharf (dari sisi Allah dan apa yang dari sisi Allah) berupa pahala (lebih baik bagi orang-orang yang berbakti) daripada kesenangan dunia.",[["لَـٰكِنِ","But"],["ٱلَّذِينَ","those who"],["ٱتَّقَوْا۟","fear"],["رَبَّهُمْ","their Lord"],["لَهُمْ","for them"],["جَنَّـٰتٌۭ","(will be) Gardens"],["تَجْرِى","flows"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","will abide forever"],["فِيهَا","in it "],["نُزُلًۭا","a hospitality"],["مِّنْ","from"],["عِندِ","[near]"],["ٱللَّهِ ۗ","Allah"],["وَمَا","And what"],["عِندَ","(is) with"],["ٱللَّهِ","Allah"],["خَيْرٌۭ","(is) best"],["لِّلْأَبْرَارِ","for the righteous"]]],"492":["(Sesungguhnya di antara Ahli Kitab ada orang yang beriman kepada Allah) seperti Abdullah bin Salam dan sahabat-sahabatnya serta Najasyi (dan kepada apa yang diturunkan kepadamu) yakni Alquran (dan kepada apa yang telah diturunkan kepada mereka) yakni Taurat dan Injil (dalam keadaan merendahkan diri) hal dari dhamir pada 'yu`minu' dengan menekankan makna 'man' dengan arti 'tawadhu`' (kepada Allah tanpa menukarkan ayat-ayat Allah) yang terdapat pada mereka dalam Taurat dan Injil berupa kebangkitan Nabi saw. (dengan harga yang sedikit) dari harta dunia, misalnya dengan menyembunyikannya karena takut kehilangan pengaruh seperti dilakukan oleh orang-orang Yahudi lainnya. (Mereka beroleh pahala) sebagai balasan atas amal perbuatan mereka (di sisi Tuhan mereka) yang diberikan kepada mereka dua kali sebagaimana terdapat dalam surah Al-Qashash (sesungguhnya Allah amat cepat perhitungan-Nya) dapat melakukan perhitungan terhadap seluruh makhluk dalam hanya setengah hari saja dari hari-hari dunia.",[["وَإِنَّ","And indeed"],["مِنْ","among"],["أَهْلِ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَمَن","(are those) who"],["يُؤْمِنُ","believe"],["بِٱللَّهِ","in Allah"],["وَمَآ","and what"],["أُنزِلَ","was revealed"],["إِلَيْكُمْ","to you"],["وَمَآ","and what"],["أُنزِلَ","was revealed"],["إِلَيْهِمْ","to them "],["خَـٰشِعِينَ","humbly submissive"],["لِلَّهِ","to Allah"],["لَا","Not"],["يَشْتَرُونَ","(do) they exchange"],["بِـَٔايَـٰتِ","[with] (the) Verses"],["ٱللَّهِ","(of) Allah"],["ثَمَنًۭا","(for) a price"],["قَلِيلًا ۗ","little"],["أُو۟لَـٰٓئِكَ","Those"],["لَهُمْ","for them"],["أَجْرُهُمْ","their reward"],["عِندَ","(is) with"],["رَبِّهِمْ ۗ","their Lord"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَرِيعُ","(is) swift"],["ٱلْحِسَابِ","(in taking) the account"]]],"493":["(Hai orang-orang yang beriman, bersabarlah) melakukan taat dan menghadapi musibah serta menghindari maksiat (dan teguhkanlah kesabaranmu) menghadapi orang-orang kafir hingga mereka tidak lebih sabar daripada kamu (dan tetaplah waspada serta siap siaga) dalam perjuangan (serta bertakwalah kepada Allah) dalam setiap keadaan (supaya kamu beruntung) merebut surga dan bebas dari neraka.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe[d]"],["ٱصْبِرُوا۟","Be steadfast"],["وَصَابِرُوا۟","and [be] patient"],["وَرَابِطُوا۟","and [be] constant"],["وَٱتَّقُوا۟","and fear"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","so that you may"],["تُفْلِحُونَ","(be) successful"]]],"494":["(Hai manusia) penduduk Mekah (bertakwalah kamu kepada Tuhanmu) artinya takutlah akan siksa-Nya dengan jalan menaati-Nya (yang telah menciptakan kamu dari satu diri) yakni Adam (dan menciptakan daripadanya istrinya) yaitu Hawa; dibaca panjang; dari salah satu tulang rusuknya yang kiri (lalu mengembangbiakkan) menyebarluaskan (dari kedua mereka itu) dari Adam dan Hawa (laki-laki yang banyak dan wanita) yang tidak sedikit jumlahnya. (Dan bertakwalah kepada Allah yang kamu saling meminta) terdapat idgam ta pada sin sedangkan menurut satu qiraat dengan takhfif yaitu membuangnya sehingga menjadi tas-aluuna (dengan nama-Nya) yang sebagian kamu mengatakan kepada sebagian lainnya, \"Saya meminta kepadamu dengan nama Allah,\" (dan) jagalah pula (hubungan silaturahmi) jangan sampai terputus. Menurut satu qiraat dibaca dengan kasrah diathafkan kepada dhamir yang terdapat pada bihi. Mereka juga biasa saling bersumpah dengan hubungan rahim. (Sesungguhnya Allah selalu mengawasi kamu) menjaga perbuatanmu dan memberi balasan terhadapnya. Maka sifat mengawasi selalu melekat dan terdapat pada Allah swt. Ayat berikut diturunkan mengenai seorang anak yatim yang meminta hartanya kepada walinya tetapi ia tidak mau memberikannya.",[["يَـٰٓأَيُّهَا","O"],["ٱلنَّاسُ","mankind"],["ٱتَّقُوا۟","Fear"],["رَبَّكُمُ","your Lord"],["ٱلَّذِى","the One Who"],["خَلَقَكُم","created you"],["مِّن","from"],["نَّفْسٍۢ","a soul"],["وَٰحِدَةٍۢ","single"],["وَخَلَقَ","and created"],["مِنْهَا","from it"],["زَوْجَهَا","its mate"],["وَبَثَّ","and dispersed"],["مِنْهُمَا","from both of them"],["رِجَالًۭا","men"],["كَثِيرًۭا","many"],["وَنِسَآءًۭ ۚ","and women"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ","Allah"],["ٱلَّذِى","(through) Whom"],["تَسَآءَلُونَ","you ask"],["بِهِۦ","[with it]"],["وَٱلْأَرْحَامَ ۚ","and the wombs"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["عَلَيْكُمْ","over you"],["رَقِيبًۭا","Ever-Watchful"]]],"495":["(Dan berikanlah kepada anak-anak yatim) yaitu anak-anak yang tidak berbapak (harta mereka) jika sudah balig (dan janganlah kamu tukar yang baik dengan yang buruk) artinya yang halal dengan yang haram dan janganlah kamu ambil harta yang baik dari anak yatim itu lalu kamu ganti dengan hartamu yang jelek (dan jangan kamu makan harta mereka) yang telah dicampur aduk (dengan hartamu. Sesungguhnya itu) maksudnya memakan yang demikian itu (adalah dosa) atau kesalahan (besar). Tatkala ayat ini turun mereka berkeberatan untuk menjadi wali anak yatim. Kemudian di antara mereka ada orang yang memiliki sepuluh atau delapan orang istri sehingga ia tak sanggup untuk berlaku adil di antara mereka, maka turunlah ayat:",[["وَءَاتُوا۟","And give"],["ٱلْيَتَـٰمَىٰٓ","(to) the orphans"],["أَمْوَٰلَهُمْ ۖ","their wealth"],["وَلَا","and (do) not"],["تَتَبَدَّلُوا۟","exchange"],["ٱلْخَبِيثَ","the bad"],["بِٱلطَّيِّبِ ۖ","with the good"],["وَلَا","and (do) not"],["تَأْكُلُوٓا۟","consume"],["أَمْوَٰلَهُمْ","their wealth"],["إِلَىٰٓ","with"],["أَمْوَٰلِكُمْ ۚ","your wealth"],["إِنَّهُۥ","Indeed, it"],["كَانَ","is"],["حُوبًۭا","a sin"],["كَبِيرًۭا","great"]]],"496":["(Dan jika kamu takut tidak akan dapat berlaku adil terhadap anak-anak yatim) sehingga sulit bagi kamu untuk menghadapi mereka lalu kamu takut pula tidak akan dapat berlaku adil di antara wanita-wanita yang kamu kawini (maka kawinilah) (apa) dengan arti siapa (yang baik di antara wanita-wanita itu bagi kamu dua, tiga atau empat orang) boleh dua, tiga atau empat tetapi tidak boleh lebih dari itu. (kemudian jika kamu tidak akan dapat berlaku adil) di antara mereka dalam giliran dan pembagian nafkah (maka hendaklah seorang saja) yang kamu kawini (atau) hendaklah kamu batasi pada (hamba sahaya yang menjadi milikmu) karena mereka tidak mempunyai hak-hak sebagaimana istri-istri lainnya. (Yang demikian itu) maksudnya mengawini empat orang istri atau seorang istri saja, atau mengambil hamba sahaya (lebih dekat) kepada (tidak berbuat aniaya) atau berlaku lalim.",[["وَإِنْ","And if"],["خِفْتُمْ","you fear"],["أَلَّا","that not"],["تُقْسِطُوا۟","you will be able to do justice"],["فِى","with"],["ٱلْيَتَـٰمَىٰ","the orphans"],["فَٱنكِحُوا۟","then marry"],["مَا","what"],["طَابَ","seems suitable"],["لَكُم","to you"],["مِّنَ","from"],["ٱلنِّسَآءِ","the women"],["مَثْنَىٰ","two"],["وَثُلَـٰثَ","or three"],["وَرُبَـٰعَ ۖ","or four"],["فَإِنْ","But if"],["خِفْتُمْ","you fear"],["أَلَّا","that not"],["تَعْدِلُوا۟","you can do justice"],["فَوَٰحِدَةً","then (marry) one"],["أَوْ","or"],["مَا","what"],["مَلَكَتْ","possesses"],["أَيْمَـٰنُكُمْ ۚ","your right hand"],["ذَٰلِكَ","That"],["أَدْنَىٰٓ","(is) more appropriate"],["أَلَّا","that (may) not"],["تَعُولُوا۟","you oppress"]]],"497":["(Berikanlah kepada wanita-wanita itu maskawin mereka) jamak dari shadaqah (sebagai pemberian) karena ketulusan dan kesucian hati (Kemudian jika mereka menyerahkan kepadamu sebagian dari maskawin itu dengan senang hati) nafsan merupakan tamyiz yang asalnya menjadi fa'il; artinya hati mereka senang untuk menyerahkan sebagian dari maskawin itu kepadamu lalu mereka berikan (maka makanlah dengan enak) atau sedap (lagi baik) akibatnya sehingga tidak membawa bencana di akhirat kelak. Ayat ini diturunkan terhadap orang yang tidak menyukainya.",[["وَءَاتُوا۟","And give"],["ٱلنِّسَآءَ","the women"],["صَدُقَـٰتِهِنَّ","their dower"],["نِحْلَةًۭ ۚ","graciously"],["فَإِن","But if"],["طِبْنَ","they remit"],["لَكُمْ","to you"],["عَن","of"],["شَىْءٍۢ","anything"],["مِّنْهُ","of it"],["نَفْسًۭا","(on their) own"],["فَكُلُوهُ","then eat it"],["هَنِيٓـًۭٔا","(in) satisfaction"],["مَّرِيٓـًۭٔا","(and) ease"]]],"498":["(Dan janganlah kamu serahkan) hai para wali (kepada orang-orang yang bebal) artinya orang-orang yang boros dari kalangan laki-laki, wanita dan anak-anak (harta kamu) maksudnya harta mereka yang berada dalam tanganmu (yang dijadikan Allah sebagai penunjang hidupmu) qiyaaman mashdar dari qaama; artinya penopang hidup dan pembela kepentinganmu karena akan mereka habiskan bukan pada tempatnya. Menurut suatu qiraat dibaca qayyima jamak dari qiimah; artinya alat untuk menilai harga benda-benda (hanya berilah mereka belanja daripadanya) maksudnya beri makanlah mereka daripadanya (dan pakaian dan ucapkanlah kepada mereka kata-kata yang baik) misalnya janjikan jika mereka telah dewasa, maka harta mereka itu akan diberikan semuanya kepada mereka.",[["وَلَا","And (do) not"],["تُؤْتُوا۟","give"],["ٱلسُّفَهَآءَ","the foolish"],["أَمْوَٰلَكُمُ","your wealth"],["ٱلَّتِى","which"],["جَعَلَ","(was) made"],["ٱللَّهُ","(by) Allah"],["لَكُمْ","for you"],["قِيَـٰمًۭا","a means of support"],["وَٱرْزُقُوهُمْ","(but) provide (for) them"],["فِيهَا","with it"],["وَٱكْسُوهُمْ","and clothe them"],["وَقُولُوا۟","and speak"],["لَهُمْ","to them"],["قَوْلًۭا","words"],["مَّعْرُوفًۭا","(of) kindness"]]],"499":["(Dan hendaklah kamu uji anak-anak yatim itu) sebelum mereka balig yakni mengenai keagamaan dan tingkah laku mereka (hingga setelah mereka sampai umur untuk kawin) artinya telah mampu untuk itu dengan melihat keadaan dan usia; menurut Imam Syafii 15 tahun penuh (maka jika menurut pendapatmu) atau penglihatanmu (mereka telah cerdas) artinya pandai menjaga agama dan harta mereka (maka serahkanlah kepada mereka itu harta-harta mereka dan janganlah kamu memakannya) hai para wali (secara berlebih-lebihan) tanpa hak; ini menjadi hal (dan dengan tergesa-gesa) untuk membelanjakannya karena khawatir (mereka dewasa) hingga harta itu harus diserahkan kepada yang berhak. (Dan barang siapa) di antara para wali (yang mampu, maka hendaklah ia menahan diri) dari mengambil dan memakan harta anak yatim itu (sedangkan siapa yang miskin, maka bolehlah ia memakan) harta itu (secara sepatutnya) artinya sekadar upah jerih payahnya. (Kemudian apabila kamu menyerahkan kepada mereka) maksudnya kepada anak-anak yatim (harta mereka, maka hendaklah kamu persaksikan terhadap mereka) yakni bahwa mereka telah menerimanya dan tanggung jawabmu telah selesai. Maksudnya ialah siapa tahu kalau-kalau terjadi persengketaan nanti, maka kamu dapat mempergunakan para saksi itu. Maka perintah ini tujuannya ialah untuk memberi petunjuk (Dan cukuplah Allah) ba merupakan tambahan (sebagai pengawas) yang mengawasi perbuatan-perbuatan hamba-Nya dan memberi mereka ganjaran. Ayat berikut ini diturunkan untuk menolak kebiasaan orang-orang jahiliah yang tidak mau memberi harta warisan kepada golongan wanita dan anak-anak.",[["وَٱبْتَلُوا۟","And test"],["ٱلْيَتَـٰمَىٰ","the orphans"],["حَتَّىٰٓ","until"],["إِذَا","[when]"],["بَلَغُوا۟","they reach[ed]"],["ٱلنِّكَاحَ","(the age of) marriage"],["فَإِنْ","then if"],["ءَانَسْتُم","you perceive"],["مِّنْهُمْ","in them"],["رُشْدًۭا","sound judgement"],["فَٱدْفَعُوٓا۟","then deliver"],["إِلَيْهِمْ","to them"],["أَمْوَٰلَهُمْ ۖ","their wealth"],["وَلَا","And (do) not"],["تَأْكُلُوهَآ","eat it"],["إِسْرَافًۭا","extravagantly"],["وَبِدَارًا","and hastily"],["أَن","(fearing) that"],["يَكْبَرُوا۟ ۚ","they will grow up"],["وَمَن","And whoever"],["كَانَ","is"],["غَنِيًّۭا","rich"],["فَلْيَسْتَعْفِفْ ۖ","then he should refrain"],["وَمَن","and whoever"],["كَانَ","is"],["فَقِيرًۭا","poor"],["فَلْيَأْكُلْ","then let him eat (of it)"],["بِٱلْمَعْرُوفِ ۚ","in a fair manner"],["فَإِذَا","Then when"],["دَفَعْتُمْ","you deliver"],["إِلَيْهِمْ","to them"],["أَمْوَٰلَهُمْ","their wealth"],["فَأَشْهِدُوا۟","then take witnesses"],["عَلَيْهِمْ ۚ","on them"],["وَكَفَىٰ","And is sufficient"],["بِٱللَّهِ","Allah"],["حَسِيبًۭا","(as) a Reckoner"]]],"500":["(Bagi laki-laki) baik anak-anak maupun karib kerabat (ada bagian) atau hak (dari harta peninggalan ibu bapak dan karib kerabat) yang meninggal dunia (dan bagi wanita ada bagian pula dari harta peninggalan ibu bapak dan karib kerabat, baik sedikit daripadanya) maksudnya dari harta itu (atau banyak) yang dijadikan Allah (sebagai hak yang telah ditetapkan) artinya hak yang pasti yang harus diserahkan kepada mereka.",[["لِّلرِّجَالِ","For the men"],["نَصِيبٌۭ","a portion"],["مِّمَّا","of what"],["تَرَكَ","(is) left"],["ٱلْوَٰلِدَانِ","(by) the parents"],["وَٱلْأَقْرَبُونَ","and the near relatives"],["وَلِلنِّسَآءِ","and for the women"],["نَصِيبٌۭ","a portion"],["مِّمَّا","of what"],["تَرَكَ","(is) left"],["ٱلْوَٰلِدَانِ","(by) parents"],["وَٱلْأَقْرَبُونَ","and the near relatives"],["مِمَّا","of what"],["قَلَّ","(is) little"],["مِنْهُ","of it"],["أَوْ","or"],["كَثُرَ ۚ","much "],["نَصِيبًۭا","a portion"],["مَّفْرُوضًۭا","obligatory"]]],"501":["(Dan apabila pembagian harta warisan dihadiri oleh karib kerabat) yakni dari golongan yang tidak beroleh warisan (dan anak-anak yatim serta orang-orang miskin, maka berilah mereka daripadanya sekadarnya) sebelum dilakukan pembagian (dan ucapkanlah) hai para wali (kepada mereka) yakni jika mereka masih kecil-kecil (kata-kata yang baik) atau lemah-lembut, seraya meminta maaf kepada kaum kerabat yang tidak mewarisi itu, bahwa harta peninggalan ini bukan milik kalian tetapi milik ahli waris yang masih kecil-kecil. Ada yang mengatakan bahwa hukum ini yakni pemberian kepada kaum kerabat yang tidak mewarisi telah dinasakhkan/dihapus. Tetapi ada pula yang mengatakan tidak, hanya manusialah yang mempermudah dan tidak melakukannya. Berdasarkan itu maka hukumnya sunah, tetapi Ibnu Abbas mengatakannya wajib.",[["وَإِذَا","And when"],["حَضَرَ","present"],["ٱلْقِسْمَةَ","(at) the (time of) division"],["أُو۟لُوا۟","(of)"],["ٱلْقُرْبَىٰ","the relatives"],["وَٱلْيَتَـٰمَىٰ","and the orphans"],["وَٱلْمَسَـٰكِينُ","and the poor"],["فَٱرْزُقُوهُم","then provide them"],["مِّنْهُ","from it"],["وَقُولُوا۟","and speak"],["لَهُمْ","to them"],["قَوْلًۭا","words"],["مَّعْرُوفًۭا","(of) kindness"]]],"502":["(Dan hendaklah bersikap waspada) maksudnya terhadap nasib anak-anak yatim (orang-orang yang seandainya meninggalkan) artinya hampir meninggalkan (di belakang mereka) sepeninggal mereka (keturunan yang lemah) maksudnya anak-anak yang masih kecil-kecil (mereka khawatir terhadap nasib mereka) akan terlantar (maka hendaklah mereka bertakwa kepada Allah) mengenai urusan anak-anak yatim itu dan hendaklah mereka lakukan terhadap anak-anak yatim itu apa yang mereka ingini dilakukan orang terhadap anak-anak mereka sepeninggal mereka nanti (dan hendaklah mereka ucapkan) kepada orang yang hendak meninggal (perkataan yang benar) misalnya menyuruhnya bersedekah kurang dari sepertiga dan memberikan selebihnya untuk para ahli waris hingga tidak membiarkan mereka dalam keadaan sengsara dan menderita.",[["وَلْيَخْشَ","And let fear "],["ٱلَّذِينَ","those who"],["لَوْ","if"],["تَرَكُوا۟","they left"],["مِنْ","from"],["خَلْفِهِمْ","behind"],["ذُرِّيَّةًۭ","offspring"],["ضِعَـٰفًا","weak"],["خَافُوا۟","(and) they would have feared"],["عَلَيْهِمْ","about them"],["فَلْيَتَّقُوا۟","So let them fear"],["ٱللَّهَ","Allah"],["وَلْيَقُولُوا۟","and let them speak"],["قَوْلًۭا","words"],["سَدِيدًا","appropriate"]]],"503":["(Sesungguhnya orang-orang yang memakan harta anak-anak yatim secara aniaya) maksudnya tanpa hak (bahwasanya mereka menelan api sepenuh perut mereka) karena harta itu akan berubah di akhirat nanti menjadi api (dan mereka akan masuk) dalam bentuk kalimat aktif atau pun pasif (api yang bernyala-nyala) yakni api neraka yang menyebabkan mereka terbakar hangus.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَأْكُلُونَ","consume"],["أَمْوَٰلَ","wealth"],["ٱلْيَتَـٰمَىٰ","(of) the orphans"],["ظُلْمًا","wrongfully"],["إِنَّمَا","only"],["يَأْكُلُونَ","they consume"],["فِى","in"],["بُطُونِهِمْ","their bellies"],["نَارًۭا ۖ","fire"],["وَسَيَصْلَوْنَ","and they will be burned"],["سَعِيرًۭا","(in) a Blazing Fire"]]],"504":["(Allah mewasiatkan atau menitahkan padamu mengenai anak-anakmu) dengan apa yang akan disebutkan ini: (yaitu bagian seorang anak lelaki sama dengan bagian dua orang anak perempuan) di antara mereka. Jika ketiga mereka itu berkumpul, maka bagi yang lelaki seperdua harta dan bagi kedua anak perempuan seperdua pula. Sedangkan jika yang ditemui itu hanya seorang anak lelaki dan seorang perempuan, maka bagi yang perempuan itu hanya sepertiga sementara bagi yang laki-laki dua pertiga. Dan sekiranya yang laki-laki itu tunggal, maka ia menghabisi semua harta (jika mereka) maksudnya anak-anak itu (hanya perempuan) saja (lebih dari dua orang maka bagi mereka dua pertiga harta yang ditinggalkan) mayat; demikian pula jika jumlah mereka dua orang karena mereka itu dua bersaudara yang tercakup dalam firman Allah swt., \"... maka bagi mereka dua pertiga dari harta peninggalan,\" mereka lebih utama apalagi mengingat bahwa seorang anak perempuan berhak sepertiga harta jika bersama seorang anak laki-laki sehingga dengan demikian jika dia bersama seorang anak perempuan lebih utama lagi dan lebih didahulukan dari hubungan apa pun. Ada pula yang mengatakan bahwa demikian itu ialah untuk menghilangkan dugaan bertambahnya bagian dengan bertambahnya bilangan, yakni tatkala timbul pengertian bahwa dengan diberikannya sepertiga bagian untuk seorang anak perempuan jika ia bersama seorang anak laki-laki, maka dua orang anak perempuan beroleh dua pertiga bagian. (Jika dia) maksudnya anak perempuan itu (seorang saja) menurut qiraat dengan baris di depan sehingga kaana dianggap sebagai tam dan bukan naqish. (maka ia memperoleh seperdua harta sedangkan untuk kedua orang tuanya) maksudnya orang tua mayat yang di sini diberi badal dengan (bagi masing-masing mereka seperenam dari harta pusaka; yakni jika si mayat itu mempunyai anak) baik laki-laki maupun wanita. Ditekankannya badal ialah untuk menyatakan bahwa kedua orang tua itu tidaklah berserikat padanya. Dan terhadap adanya anak dianggap adanya cucu, begitu pula terhadap adanya bapak adanya kakek. (Jika si mayat tidak mempunyai anak dan dia diwarisi oleh kedua orang tuanya) saja atau bersama istrinya (maka bagi ibunya) dapat dibaca li-ummihi dengan hamzah baris di depan dan boleh pula limmihi dengan hamzah baris di bawah untuk meringankan bertemunya dhammah dan kasrah pada dua tempat yang berdekatan (sepertiga) maksudnya sepertiga dari harta yang telah dibagikan kepada pihak istri, sedangkan sisanya buat bapak. (Jika yang meninggal itu mempunyai beberapa orang saudara) maksudnya dua orang atau lebih, baik laki-laki atau perempuan (maka bagi ibunya seperenam) sedangkan sisanya untuk bapaknya, sementara saudara-saudaranya itu tidak beroleh bagian apa-apa. Dan pembagian warisan seperti tersebut di atas itu ialah (setelah) dilaksanakannya (wasiat yang dibuatnya) dibaca yuushii atau yuushaa dalam bentuk aktif atau pun pasif (atau) dibayarnya (utangnya). Dan disebutkannya lebih dulu pemenuhan wasiat daripada pembayaran utang, walaupun pelaksanaannya dibelakangkan ialah dengan maksud untuk tidak mengabaikannya. (Mengenai orang tuamu dan anak-anakmu) menjadi mubtada sedangkan khabarnya ialah: (tidaklah kamu ketahui manakah yang lebih dekat kepadamu manfaatnya) di dunia dan di akhirat. Ada orang yang mengira bahwa putranyalah yang lebih banyak kegunaannya kepadanya, lalu diberinya harta warisan sehingga dengan demikian ternyatalah bahwa bapaklah yang lebih bermanfaat bagi manusia, demikian sebaliknya. Maka yang mengetahui soal itu hanyalah Allah swt. dan itulah sebabnya diwajibkan-Nya pembagian pusaka. (Ini adalah ketetapan dari Allah; sesungguhnya Allah Maha Mengetahui) terhadap makhluk-Nya (lagi Maha Bijaksana) tentang peraturan-peraturan yang diberikan-Nya kepada mereka; artinya Dia tetap bersifat bijaksana dalam semuanya itu.",[["يُوصِيكُمُ","Instructs you"],["ٱللَّهُ","Allah"],["فِىٓ","concerning"],["أَوْلَـٰدِكُمْ ۖ","your children "],["لِلذَّكَرِ","for the male"],["مِثْلُ","like"],["حَظِّ","(the) portion"],["ٱلْأُنثَيَيْنِ ۚ","(of) two females"],["فَإِن","But if"],["كُنَّ","there are"],["نِسَآءًۭ","(only) women"],["فَوْقَ","more (than)"],["ٱثْنَتَيْنِ","two"],["فَلَهُنَّ","then for them"],["ثُلُثَا","two thirds"],["مَا","(of) what"],["تَرَكَ ۖ","he left"],["وَإِن","And if"],["كَانَتْ","(there) is"],["وَٰحِدَةًۭ","(only) one"],["فَلَهَا","then for her"],["ٱلنِّصْفُ ۚ","(is) half"],["وَلِأَبَوَيْهِ","And for his parents"],["لِكُلِّ","for each"],["وَٰحِدٍۢ","one"],["مِّنْهُمَا","of them"],["ٱلسُّدُسُ","a sixth"],["مِمَّا","of what"],["تَرَكَ","(is) left"],["إِن","if"],["كَانَ","is"],["لَهُۥ","for him"],["وَلَدٌۭ ۚ","a child"],["فَإِن","But if"],["لَّمْ","not"],["يَكُن","is"],["لَّهُۥ","for him"],["وَلَدٌۭ","any child"],["وَوَرِثَهُۥٓ","and inherit[ed] him"],["أَبَوَاهُ","his parents"],["فَلِأُمِّهِ","then for his mother"],["ٱلثُّلُثُ ۚ","(is) one third"],["فَإِن","And if"],["كَانَ","are"],["لَهُۥٓ","for him"],["إِخْوَةٌۭ","brothers and sisters"],["فَلِأُمِّهِ","then for his mother"],["ٱلسُّدُسُ ۚ","(is) the sixth"],["مِنۢ","from"],["بَعْدِ","after"],["وَصِيَّةٍۢ","any will"],["يُوصِى","he has made"],["بِهَآ","[of which]"],["أَوْ","or"],["دَيْنٍ ۗ","any debt"],["ءَابَآؤُكُمْ","Your parents"],["وَأَبْنَآؤُكُمْ","and your children "],["لَا","not"],["تَدْرُونَ","you know"],["أَيُّهُمْ","which of them"],["أَقْرَبُ","(is) nearer"],["لَكُمْ","to you"],["نَفْعًۭا ۚ","(in) benefit"],["فَرِيضَةًۭ","An obligation"],["مِّنَ","from"],["ٱللَّهِ ۗ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["عَلِيمًا","All-Knowing"],["حَكِيمًۭا","All-Wise"]]],"505":["(Dan bagi kamu, suami-suami, seperdua dari harta peninggalan istri-istrimu jika mereka tidak mempunyai anak) baik dari kamu maupun dari bekas suaminya dulu. (Tetapi jika mereka mempunyai anak, maka kamu mendapat seperempat dari harta peninggalan, yakni setelah dipenuhinya wasiat yang mereka buat atau dibayarnya utang mereka.) Dalam hal ini cucu dianggap sama dengan anak menurut ijmak. (Dan bagi mereka) artinya para istri itu baik mereka berbilang atau tidak (seperempat dari harta yang kamu tinggalkan jika kamu tidak mempunyai anak; dan jika kamu mempunyai anak) baik dari istrimu itu maupun dari bekas istrimu (maka bagi mereka seperdelapan dari harta peninggalanmu, yakni setelah dipenuhinya wasiat yang kamu buat atau dibayarnya utangmu). Dalam hal ini cucu dianggap sama dengan anak menurut ijmak. (Jika seorang laki-laki yang diwarisi itu) menjadi sifat, sedangkan khabarnya: (kalalah) artinya tidak meninggalkan bapak dan tidak pula anak (atau perempuan) yang mewaris secara kalalah (tetapi ia mempunyai) maksudnya yang diwarisi itu (seorang saudara laki-laki atau seorang saudara perempuan) maksudnya yang seibu, dan jelas-jelas dibaca oleh Ibnu Masud dan lain-lain (maka masing-masing jenis saudara itu memperoleh seperenam) harta peninggalan. (Tetapi jika mereka itu) maksudnya saudara-saudara yang seibu itu, baik laki-laki maupun perempuan (lebih daripada itu) maksudnya lebih dari seorang (maka mereka berserikat dalam sepertiga harta) dengan bagian yang sama antara laki-laki dan perempuan (sesudah dipenuhinya wasiat yang dibuatnya atau dibayarnya utangnya tanpa memberi mudarat) menjadi hal dari dhamir yang terdapat pada yuushaa; artinya tidak menyebabkan adanya kesusahan bagi para ahli waris, misalnya dengan berwasiat lebih dari sepertiga harta (sebagai amanat) atau pesan, dan merupakan mashdar yang mengukuhkan dari yuushiikum (dari Allah, dan Allah Maha Mengetahui) faraid atau tata cara pembagian pusaka yang diatur-Nya buat makhluk-Nya (lagi Maha Penyantun) dengan menangguhkan hukuman terhadap orang-orang yang melanggarnya. Kemudian mengenai pembagian pusaka terhadap ahli-ahli waris tersebut yang mengandung keraguan dengan adanya halangan seperti pembunuhan atau perbedaan agama dan menjadi murtad, maka penjelasannya diserahkan pada sunah.",[["۞ وَلَكُمْ","And for you"],["نِصْفُ","(is) half"],["مَا","(of) what"],["تَرَكَ","(is) left"],["أَزْوَٰجُكُمْ","by your wives"],["إِن","if"],["لَّمْ","not"],["يَكُن","is"],["لَّهُنَّ","for them"],["وَلَدٌۭ ۚ","a child"],["فَإِن","But if"],["كَانَ","is"],["لَهُنَّ","for them"],["وَلَدٌۭ","a child"],["فَلَكُمُ","then for you"],["ٱلرُّبُعُ","(is) the fourth"],["مِمَّا","of what"],["تَرَكْنَ ۚ","they left"],["مِنۢ","from"],["بَعْدِ","after"],["وَصِيَّةٍۢ","any will"],["يُوصِينَ","they have made"],["بِهَآ","[for which]"],["أَوْ","or"],["دَيْنٍۢ ۚ","any debt"],["وَلَهُنَّ","And for them"],["ٱلرُّبُعُ","(is) the fourth"],["مِمَّا","of what"],["تَرَكْتُمْ","you left"],["إِن","if"],["لَّمْ","not"],["يَكُن","is"],["لَّكُمْ","for you"],["وَلَدٌۭ ۚ","a child"],["فَإِن","But if"],["كَانَ","is"],["لَكُمْ","for you"],["وَلَدٌۭ","a child"],["فَلَهُنَّ","then for them"],["ٱلثُّمُنُ","(is) the eighth"],["مِمَّا","of what"],["تَرَكْتُم ۚ","you left"],["مِّنۢ","from"],["بَعْدِ","after"],["وَصِيَّةٍۢ","any will"],["تُوصُونَ","you have made"],["بِهَآ","[for which]"],["أَوْ","or"],["دَيْنٍۢ ۗ","any debt"],["وَإِن","And if"],["كَانَ","[is]"],["رَجُلٌۭ","a man"],["يُورَثُ","(whose wealth) is to be inherited"],["كَلَـٰلَةً","(has) no parent or child"],["أَوِ","or"],["ٱمْرَأَةٌۭ","a women"],["وَلَهُۥٓ","and for him"],["أَخٌ","(is) a brother"],["أَوْ","or"],["أُخْتٌۭ","a sister"],["فَلِكُلِّ","then for each"],["وَٰحِدٍۢ","one"],["مِّنْهُمَا","of (the) two"],["ٱلسُّدُسُ ۚ","(is) the sixth"],["فَإِن","But if"],["كَانُوٓا۟","they are"],["أَكْثَرَ","more"],["مِن","than"],["ذَٰلِكَ","that"],["فَهُمْ","then they"],["شُرَكَآءُ","(are) partners"],["فِى","in"],["ٱلثُّلُثِ ۚ","the third"],["مِنۢ","from"],["بَعْدِ","after"],["وَصِيَّةٍۢ","any will"],["يُوصَىٰ","was made"],["بِهَآ","[for which]"],["أَوْ","or"],["دَيْنٍ","any debt"],["غَيْرَ","without"],["مُضَآرٍّۢ ۚ","(being) harmful"],["وَصِيَّةًۭ","An ordinance"],["مِّنَ","from"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knowing"],["حَلِيمٌۭ","All-Forbearing"]]],"506":["(Itulah) maksudnya hukum-hukum tersebut semenjak urusan anak yatim hingga berikutnya (ketentuan-ketentuan Allah) syariat-syariat yang ditetapkan-Nya buat hamba-hamba-Nya agar mereka patuhi dan tidak dikhianati. (Barang siapa yang taat kepada Allah dan Rasul-Nya) mengenai hukum-hukum yang ditetapkan-Nya itu (maka akan dimasukkan-Nya) ada yang membaca nudkhiluhu; artinya Kami masukkan ia, dengan maksud merubah pembicaraan kepada orang pertama (ke dalam surga yang mengalir di bawahnya sungai-sungai, kekal mereka di dalamnya, dan itulah kemenangan yang besar).",[["تِلْكَ","These"],["حُدُودُ","(are the) limits"],["ٱللَّهِ ۚ","(of) Allah"],["وَمَن","and whoever"],["يُطِعِ","obeys"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["يُدْخِلْهُ","He will admit him"],["جَنَّـٰتٍۢ","(to) Gardens"],["تَجْرِى","flows"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers "],["خَـٰلِدِينَ","(will) abide forever"],["فِيهَا ۚ","in it"],["وَذَٰلِكَ","And that"],["ٱلْفَوْزُ","(is) the success"],["ٱلْعَظِيمُ","[the] great"]]],"507":["(Dan siapa yang mendurhakai Allah dan Rasul-Nya serta melanggar aturan-aturan-Nya, maka akan dimasukkan-Nya) ada dua versi dengan memakai ya dan ada pula dengan memakai nun (ke dalam api neraka, kekal ia di dalamnya dan baginya) di dalamnya (siksa yang menghinakan) di samping menciutkan hati. Pada kedua ayat terdapat lafal man sedangkan pada khaalidiina makna atau artinya.",[["وَمَن","And whoever"],["يَعْصِ","disobeys"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["وَيَتَعَدَّ","and transgresses"],["حُدُودَهُۥ","His limits "],["يُدْخِلْهُ","He will admit him"],["نَارًا","(to) Fire"],["خَـٰلِدًۭا","(will) abide forever"],["فِيهَا","in it"],["وَلَهُۥ","And for him"],["عَذَابٌۭ","(is) a punishment"],["مُّهِينٌۭ","humiliating"]]],"508":["(Dan wanita-wanita yang melakukan perbuatan keji) maksudnya berzina di antara wanita-wanitamu (maka persaksikanlah mereka itu kepada empat orang saksi di antaramu) maksudnya di antara laki-lakimu yang beragama Islam. (Maka jika mereka memberikan kesaksian) terhadap perbuatan mereka itu (maka tahanlah mereka itu) atau kurunglah (dalam rumah) dan laranglah mereka bergaul dengan manusia (sampai mereka diwafatkan oleh maut) maksudnya oleh malaikat maut (atau) hingga (Allah memberi bagi mereka jalan lain) yakni jalan untuk membebaskan mereka dari hukuman semacam itu. Demikianlah hukuman mereka pada awal Islam lalu mereka diberi jalan lain yaitu digantinya dengan hukum dera sebanyak seratus kali serta membuangnya dari kampung halamannya selama setahun yakni bagi yang belum kawin dan dengan merajam wanita-wanita yang sudah kawin. Dalam hadis tersebut bahwa tatkala hukuman itu diumumkan, bersabdalah Nabi saw., \"Terimalah daripadaku, contohlah kepadaku karena Allah telah memberikan bagi mereka jalan lepas!\" Riwayat Muslim.",[["وَٱلَّـٰتِى","And those who"],["يَأْتِينَ","commit"],["ٱلْفَـٰحِشَةَ","[the] immorality"],["مِن","from"],["نِّسَآئِكُمْ","your women"],["فَٱسْتَشْهِدُوا۟","then call to witness"],["عَلَيْهِنَّ","against them"],["أَرْبَعَةًۭ","four"],["مِّنكُمْ ۖ","among you"],["فَإِن","And if"],["شَهِدُوا۟","they testify"],["فَأَمْسِكُوهُنَّ","then confine them"],["فِى","in"],["ٱلْبُيُوتِ","their houses"],["حَتَّىٰ","until"],["يَتَوَفَّىٰهُنَّ","comes to them"],["ٱلْمَوْتُ","[the] death"],["أَوْ","or"],["يَجْعَلَ","makes"],["ٱللَّهُ","Allah"],["لَهُنَّ","for them"],["سَبِيلًۭا","a way"]]],"509":["(Dan mengenai dua orang) dengan nun yang memakai atau tanpa tasydid (yang melakukannya) maksudnya perbuatan keji, yaitu berzina atau homoseksual (di antara kamu) maksudnya kaum lelaki (maka berilah mereka hukuman) dengan mencela dan memukul mereka dengan terompah. (Kemudian jika mereka bertobat) daripadanya (dan memperbaiki perbuatan mereka) (maka tinggalkanlah mereka) dan jangan disakiti lagi. (Sesungguhnya Allah Maha Penerima tobat) terhadap orang yang sadar (lagi Maha Penyayang) kepadanya. Ayat ini telah dihapus/dimansukh hukumnya dengan ayat had, jika yang dimaksud karena berzina. Demikian pula menurut Syafii jika yang dimaksud karena homoseksual. Hanya menurutnya pula, orang yang \"dikerjai\" tidaklah dirajam walaupun telah beristri, hanya dipukul dan diasingkan. Bahwa yang dimaksud itu homoseksual lebih kuat dengan alasan adanya dhamir tatsniah huma dan lain-lain. Menurut golongan yang pertama yang dimaksud dengan kedua mereka itu ialah pezina yang laki-laki dan yang perempuan. Tetapi pendapat ini ditolak oleh golongan Syafii dengan penjelasan yang diberikan kemudian dengan hubungannya yang berkaitan dengan dhamir laki-laki dan berserikatnya kedua mereka dalam menerima hukuman, bertobat dan diisolir. Dan ini khusus bagi pihak laki-laki, karena sebagaimana kita ketahui bagi pihak wanita ialah tahanan rumah.",[["وَٱلَّذَانِ","And the two who"],["يَأْتِيَـٰنِهَا","commit it"],["مِنكُمْ","among you"],["فَـَٔاذُوهُمَا ۖ","then punish both of them"],["فَإِن","But if"],["تَابَا","they repent"],["وَأَصْلَحَا","and correct themselves"],["فَأَعْرِضُوا۟","then turn away"],["عَنْهُمَآ ۗ","from both of them"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["تَوَّابًۭا","Oft-Forgiving"],["رَّحِيمًا","Most-Merciful"]]],"510":["(Sesungguhnya tobat di isi Allah) yakni yang pasti diterima di sisi-Nya berkat kemurahan-Nya (ialah bagi orang-orang yang mengerjakan kejahatan) atau maksiat (disebabkan kejahilan) menjadi hal artinya tidak tahu bahwa dengan itu berarti mendurhakai Allah (kemudian mereka bertobat dalam) waktu (dekat) yakni sebelum mengalami sekarat (maka mereka itulah yang diterima tobatnya oleh Allah) artinya diterima-Nya tobat mereka (dan Allah Maha Mengetahui) akan makhluk-Nya (lagi Maha Bijaksana) mengenai tindakan-Nya terhadap mereka.",[["إِنَّمَا","Only"],["ٱلتَّوْبَةُ","the acceptance of repentance"],["عَلَى","by"],["ٱللَّهِ","Allah"],["لِلَّذِينَ","(is) for those who"],["يَعْمَلُونَ","do"],["ٱلسُّوٓءَ","the evil"],["بِجَهَـٰلَةٍۢ","in ignorance"],["ثُمَّ","then"],["يَتُوبُونَ","they repent"],["مِن","from"],["قَرِيبٍۢ","soon after"],["فَأُو۟لَـٰٓئِكَ","Then those"],["يَتُوبُ","will have forgiveness"],["ٱللَّهُ","(from) Allah"],["عَلَيْهِمْ ۗ","upon them"],["وَكَانَ","and is"],["ٱللَّهُ","Allah"],["عَلِيمًا","All-Knowing"],["حَكِيمًۭا","All-Wise"]]],"511":["(Dan tidaklah dikatakan tobat bagi orang-orang yang mengerjakan kejahatan) atau dosa (hingga ketika ajal datang kepada salah seorang mereka) dan nyawanya hendak lepas (lalu dikatakannya) ketika menyaksikan apa yang sedang dialaminya (\"Sesungguhnya saya bertobat sekarang.\") karena itu tidaklah bermanfaat dan tidak akan diterima oleh Allah tobatnya. (Dan tidak pula orang-orang yang mati sedangkan mereka berada dalam kekafiran) yakni jika mereka bertobat di akhirat sewaktu menyaksikan azab, maka tidak pula akan diterima. (Mereka itu Kami siapkan) sediakan (bagi mereka siksa yang pedih) yang menyakitkan.",[["وَلَيْسَتِ","And not"],["ٱلتَّوْبَةُ","(is) the acceptance of repentance"],["لِلَّذِينَ","for those who"],["يَعْمَلُونَ","do"],["ٱلسَّيِّـَٔاتِ","the evil deeds"],["حَتَّىٰٓ","until"],["إِذَا","when"],["حَضَرَ","approaches"],["أَحَدَهُمُ","one of them"],["ٱلْمَوْتُ","[the] death"],["قَالَ","he says"],["إِنِّى","Indeed I"],["تُبْتُ","repent"],["ٱلْـَٔـٰنَ","now"],["وَلَا","and not"],["ٱلَّذِينَ","those who"],["يَمُوتُونَ","die"],["وَهُمْ","while they"],["كُفَّارٌ ۚ","(are) disbelievers"],["أُو۟لَـٰٓئِكَ","Those "],["أَعْتَدْنَا","We have prepared"],["لَهُمْ","for them"],["عَذَابًا","a punishment"],["أَلِيمًۭا","painful"]]],"512":["(Hai orang-orang yang beriman, tidak halal bagi kamu mewarisi wanita) maksudnya diri mereka (dengan paksa) dibaca karhan atau kurhan; artinya tanpa kemauan dan kerelaan mereka. Di zaman jahiliah mereka biasa mewarisi wanita-wanita, istri karib kerabat mereka. Jika mereka kehendaki mereka dapat mengawininya tanpa maskawin, atau mereka kawinkan lalu diambil maskawinnya, atau mereka halangi kawin sampai wanita itu menebus dirinya dengan harta warisan yang diperolehnya atau mereka tunggu sampai meninggal lalu mereka warisi hartanya; maka mereka dilarang demikian itu. (Dan tidak pula) bahwa (kamu menyusahkan mereka) artinya kamu halangi istri-istrimu buat mengawini laki-laki lain dengan menahan mereka padahal tak ada keinginanmu lagi terhadap mereka selain dari menyusahkan belaka (karena hendak mengambil kembali sebagian dari apa yang telah kamu berikan kepada mereka) berupa mahar (kecuali jika mereka melakukan pekerjaan keji yang nyata) dengan ya baris di atas dan baris di bawah, yang nyata atau yang dinyatakan, artinya zina atau nusyuz; maka ketika itu bolehlah kamu menyusahkan mereka hingga mereka melakukan khuluk atau menebus diri mereka (dan pergaulilah mereka secara patut) artinya secara baik-baik, biar dalam perkataan maupun dalam memberi nafkah lahir atau batin. (Maka jika kamu tidak menyukai mereka) hendaklah bersabar (karena mungkin kamu tidak menyukai sesuatu tetapi Allah menjadikan padanya kebaikan yang banyak). Siapa tahu hal itu dilakukan-Nya misalnya dengan menganugerahimu anak yang saleh.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe[d]"],["لَا","Not"],["يَحِلُّ","(is) lawful"],["لَكُمْ","for you"],["أَن","that"],["تَرِثُوا۟","you inherit"],["ٱلنِّسَآءَ","the women"],["كَرْهًۭا ۖ","(by) force"],["وَلَا","And not"],["تَعْضُلُوهُنَّ","you constraint them"],["لِتَذْهَبُوا۟","so that you may take"],["بِبَعْضِ","a part"],["مَآ","(of) what"],["ءَاتَيْتُمُوهُنَّ","you have given them"],["إِلَّآ","except"],["أَن","that"],["يَأْتِينَ","they commit"],["بِفَـٰحِشَةٍۢ","immorality"],["مُّبَيِّنَةٍۢ ۚ","open"],["وَعَاشِرُوهُنَّ","And live with them"],["بِٱلْمَعْرُوفِ ۚ","in kindness"],["فَإِن","But if"],["كَرِهْتُمُوهُنَّ","you dislike them"],["فَعَسَىٰٓ","then perhaps"],["أَن","that"],["تَكْرَهُوا۟","you dislike"],["شَيْـًۭٔا","a thing"],["وَيَجْعَلَ","and has placed"],["ٱللَّهُ","Allah"],["فِيهِ","in it"],["خَيْرًۭا","good"],["كَثِيرًۭا","much"]]],"513":["(Dan jika kamu bermaksud hendak mengganti istrimu dengan istri yang lain) artinya kamu ambil dia sebagai penggantinya setelah kamu ceraikan istrimu yang pertama itu (dan) sungguh (kamu telah memberikan kepada salah seorang di antara mereka) maksudnya istri-istri itu (harta yang banyak) sebagai maskawinnya (maka janganlah kamu mengambil kembali daripadanya barang sedikit pun. Apakah kamu akan mengambilnya kembali secara aniaya) dengan zalim (dan dengan -memikul- dosa yang nyata?) Dinashabkan keduanya karena kedudukan mereka sebagai hal sedangkan pertanyaan berikut maksudnya sebagai celaan dan penolakan:",[["وَإِنْ","And if"],["أَرَدتُّمُ","you intend"],["ٱسْتِبْدَالَ","replacing"],["زَوْجٍۢ","a wife"],["مَّكَانَ","(in) place"],["زَوْجٍۢ","(of) a wife"],["وَءَاتَيْتُمْ","and you have given"],["إِحْدَىٰهُنَّ","one of them"],["قِنطَارًۭا","heap (of gold)"],["فَلَا","then (do) not"],["تَأْخُذُوا۟","take away"],["مِنْهُ","from it"],["شَيْـًٔا ۚ","anything"],["أَتَأْخُذُونَهُۥ","Would you take it"],["بُهْتَـٰنًۭا","(by) slander"],["وَإِثْمًۭا","and a sin"],["مُّبِينًۭا","open"]]],"514":["(Bagaimana kamu akan mengambilnya kembali) artinya dengan alasan apa (padahal sebagian kamu telah bergaul dengan yang lain) atau telah berhubungan sebagai suami istri dengan bercampur yang telah mensahkan maskawin (dan mereka telah mengambil daripadamu perjanjian) atau pengakuan (yang erat) atau berat, yakni berupa perintah Ilahi agar memegang mereka secara baik-baik atau melepas mereka secara baik-baik pula.",[["وَكَيْفَ","And how"],["تَأْخُذُونَهُۥ","could you take it"],["وَقَدْ","when surely"],["أَفْضَىٰ","has gone "],["بَعْضُكُمْ","one of you"],["إِلَىٰ","to"],["بَعْضٍۢ","another"],["وَأَخَذْنَ","and they have taken"],["مِنكُم","from you"],["مِّيثَـٰقًا","covenant"],["غَلِيظًۭا","strong"]]],"515":["(Dan janganlah kamu kawini apa) maksudnya siapa (Di antara wanita-wanita yang telah dikawini oleh bapakmu kecuali) artinya selain dari (yang telah berlalu) dari perbuatanmu itu, maka dimaafkan. (Sesungguhnya hal itu) maksudnya mengawini mereka itu (adalah perbuatan keji) atau busuk (suatu kutukan) maksudnya sesuatu yang menyebabkan timbulnya kutukan dari Allah, yang berarti kemurkaan-Nya yang amat sangat (dan sejahat-jahat) seburuk-buruk (jalan) yang ditempuh.",[["وَلَا","And (do) not"],["تَنكِحُوا۟","marry"],["مَا","whom"],["نَكَحَ","married"],["ءَابَآؤُكُم","your fathers"],["مِّنَ","of"],["ٱلنِّسَآءِ","the women"],["إِلَّا","except"],["مَا","what"],["قَدْ","has"],["سَلَفَ ۚ","passed before"],["إِنَّهُۥ","indeed it"],["كَانَ","was"],["فَـٰحِشَةًۭ","an immorality"],["وَمَقْتًۭا","and hateful"],["وَسَآءَ","and (an) evil"],["سَبِيلًا","way"]]],"516":["(Diharamkan atas kamu ibu-ibumu) maksudnya mengawini mereka dan ini mencakup pula nenek, baik dari pihak bapak maupun dari pihak ibu (dan anak-anak perempuanmu) termasuk cucu-cucumu yang perempuan terus ke bawah (saudara-saudaramu yang perempuan) baik dari pihak bapak maupun dari pihak ibu (saudara-saudara bapakmu yang perempuan) termasuk pula saudara-saudara kakekmu (saudara-saudara ibumu yang perempuan) termasuk pula saudara-saudara nenekmu (anak-anak perempuan dari saudaramu yang laki-laki, anak-anak perempuan dari saudaramu yang perempuan) maksudnya keponakan-keponakanmu dan tercakup pula di dalamnya anak-anak mereka (ibu-ibumu yang menyusui kamu) maksudnya ibu-ibu susuan, yakni sebelum usiamu mencapai dua tahun dan sekurang-kurangnya lima kali susuan sebagaimana dijelaskan oleh hadis (saudara-saudara perempuanmu sesusuan). Kemudian dalam sunah ditambahkan anak-anak perempuan daripadanya, yaitu wanita-wanita yang disusukan oleh wanita-wanita yang telah dicampurinya, berikut saudara-saudara perempuan dari bapak dan dari ibu, serta anak-anak perempuan dari saudara laki-laki dan anak-anak perempuan dari saudara perempuannya, berdasarkan sebuah hadis yang berbunyi, \"Haram disebabkan penyusuan apa yang haram oleh sebab pertalian darah.\" Riwayat Bukhari dan Muslim. (ibu-ibu istrimu, mertua, dan anak-anak tirimu) jamak rabiibah yaitu anak perempuan istri dari suaminya yang lain (yang berada dalam asuhanmu) mereka berada dalam pemeliharaan kalian; kalimat ini berkedudukan sebagai kata sifat dari lafal rabaaib (dan istri-istrimu yang telah kamu campuri) telah kalian setubuhi (tetapi jika kamu belum lagi mencampuri mereka, maka tidaklah berdosa kamu) mengawini anak-anak perempuan mereka, jika kamu telah menceraikan mereka (dan diharamkan istri-istri anak kandungmu) yakni yang berasal dari sulbimu, berbeda halnya dengan anak angkatmu, maka kamu boleh kawin dengan janda-janda mereka (dan bahwa kamu himpun dua orang perempuan yang bersaudara) baik saudara dari pertalian darah maupun sepersusuan, dan menghimpun seorang perempuan dengan saudara perempuan bapaknya atau saudara perempuan ibunya tetapi diperbolehkan secara \"tukar lapik\" atau \"turun ranjang\" atau memiliki kedua mereka sekaligus asal yang dicampuri itu hanya salah seorang di antara mereka (kecuali) atau selain (yang telah terjadi di masa lalu) yakni di masa jahiliah sebagian dari apa yang disebutkan itu, maka kamu tidaklah berdosa karenanya. (Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["حُرِّمَتْ","Forbidden"],["عَلَيْكُمْ","to you"],["أُمَّهَـٰتُكُمْ","(are) your mothers"],["وَبَنَاتُكُمْ","and your daughters"],["وَأَخَوَٰتُكُمْ","and your sisters"],["وَعَمَّـٰتُكُمْ","and your father's sisters"],["وَخَـٰلَـٰتُكُمْ","and your mother's sisters"],["وَبَنَاتُ","and daughters"],["ٱلْأَخِ","(of) brothers"],["وَبَنَاتُ","and daughters"],["ٱلْأُخْتِ","(of) sisters"],["وَأُمَّهَـٰتُكُمُ","and (the) mothers"],["ٱلَّـٰتِىٓ","who"],["أَرْضَعْنَكُمْ","nursed you"],["وَأَخَوَٰتُكُم","and your sisters"],["مِّنَ","from"],["ٱلرَّضَـٰعَةِ","the nursing"],["وَأُمَّهَـٰتُ","and mothers"],["نِسَآئِكُمْ","(of) your wives"],["وَرَبَـٰٓئِبُكُمُ","and your step daughters"],["ٱلَّـٰتِى","who"],["فِى","(are) in"],["حُجُورِكُم","your guardianship"],["مِّن","of"],["نِّسَآئِكُمُ","your women"],["ٱلَّـٰتِى","whom"],["دَخَلْتُم","you had relations"],["بِهِنَّ","with them"],["فَإِن","but if"],["لَّمْ","not"],["تَكُونُوا۟","you had"],["دَخَلْتُم","relations"],["بِهِنَّ","with them"],["فَلَا","then (there is) no"],["جُنَاحَ","sin"],["عَلَيْكُمْ","on you"],["وَحَلَـٰٓئِلُ","And wives"],["أَبْنَآئِكُمُ","(of) your sons"],["ٱلَّذِينَ","those who"],["مِنْ","(are) from"],["أَصْلَـٰبِكُمْ","your loins"],["وَأَن","and that"],["تَجْمَعُوا۟","you gather together"],["بَيْنَ","[between]"],["ٱلْأُخْتَيْنِ","two sisters"],["إِلَّا","except"],["مَا","what"],["قَدْ","has"],["سَلَفَ ۗ","passed before"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["غَفُورًۭا","Oft-Forgiving"],["رَّحِيمًۭا","Most-Merciful"]]]});